window.FAQ=(window.FAQ||[]).concat([
 {id:'psx-001',thema:'praktijk-software',vraag:'Hoe leg ik vast dat een klant bepaalde informatie niet wilde geven?',antwoord:`Noteer welke vraag je stelde en welk antwoord of welke weigering je kreeg. Leg vast welke gevolgen dit heeft voor het advies. Laat de klant dit bij voorkeur bevestigen. Ontbreekt essentiële informatie, overweeg dan of je wel kunt adviseren.`,tags:['intake','vastlegging','weigering'],bron:'Wft'},
 {id:'psx-002',thema:'praktijk-software',vraag:'Wat doe ik als partners tijdens de intake tegenstrijdige wensen hebben?',antwoord:`Leg beide wensen apart vast in het klantprofiel. Bespreek de spanning tussen de wensen openlijk. Noteer welke keuze het stel uiteindelijk maakt en waarom. Zo blijft de afweging later te volgen.`,tags:['intake','partners','klantprofiel'],bron:''},
 {id:'psx-003',thema:'praktijk-software',vraag:'Hoe ga ik om met een intake via videobellen?',antwoord:`Een intake op afstand is mogelijk, maar de eisen aan inventarisatie blijven gelijk. Leg vast dat het gesprek op afstand plaatsvond. Controleer de identiteit zorgvuldig. Stuur een samenvatting van het gesprek ter bevestiging.`,tags:['intake','videobellen','identificatie'],bron:''},
 {id:'psx-004',thema:'praktijk-software',vraag:'Moet ik een gespreksverslag van de intake maken?',antwoord:`De wet schrijft geen vorm voor, maar je moet de inventarisatie kunnen aantonen. Een kort verslag met de belangrijkste wensen en omstandigheden helpt daarbij. Stuur het verslag bij voorkeur naar de klant. Bewaar het in het dossier.`,tags:['intake','verslag','vastlegging'],bron:'Wft'},
 {id:'psx-005',thema:'praktijk-software',vraag:'Hoe inventariseer ik kennis en ervaring van een klant?',antwoord:`Stel concrete vragen over eerdere hypotheken, beleggingen en financiële keuzes. Laat de klant risicos in eigen woorden uitleggen. Leg het antwoord vast en koppel het aan de productkeuze. Een standaard vinkje zonder toelichting is zwak bewijs.`,tags:['intake','kennis-ervaring','klantprofiel'],bron:'Wft'},
 {id:'psx-006',thema:'praktijk-software',vraag:'Hoe stel ik de risicobereidheid vast bij een hypotheekklant?',antwoord:`Bespreek concrete scenarios, zoals een rentestijging of inkomensdaling. Vraag hoe de klant daarop zou reageren. Leg het antwoord vast en verwijs ernaar bij keuzes als rentevaste periode en aflossingsvorm. Vermijd alleen een score zonder uitleg.`,tags:['risicobereidheid','intake','klantprofiel'],bron:''},
 {id:'psx-007',thema:'praktijk-software',vraag:'Wanneer moet ik de inventarisatie opnieuw doen?',antwoord:`Doe dat als de situatie van de klant wezenlijk verandert. Denk aan een nieuwe baan, scheiding, gezinsuitbreiding of een lange pauze in het traject. Ook bij een nieuw adviesmoment is een actuele inventarisatie nodig. Leg de update met datum vast.`,tags:['inventarisatie','actualisatie','dossier'],bron:''},
 {id:'psx-008',thema:'praktijk-software',vraag:'Wat leg ik vast als een klant execution only wil?',antwoord:`Leg vast dat de klant bewust geen advies wil en dat je dit hebt uitgelegd. Noteer welke informatie je wel hebt gegeven. Controleer of execution only voor dit product en deze klant past. Twijfel je, leg dan je afweging vast.`,tags:['execution-only','vastlegging','dienstverlening'],bron:'Wft'},
 {id:'psx-009',thema:'praktijk-software',vraag:'Hoe ga ik om met een klant die al een offerte van een andere partij heeft?',antwoord:`Behandel dit als een gewone adviesaanvraag met volledige inventarisatie. Neem de bestaande offerte mee als informatie, niet als uitgangspunt. Leg vast welke opdracht de klant je geeft. Maak afspraken over de vergoeding voordat je begint.`,tags:['intake','opdracht','offerte'],bron:''},
 {id:'psx-010',thema:'praktijk-software',vraag:'Waarom is een opdrachtbevestiging belangrijk?',antwoord:`Daarin staat wat je doet, wat je niet doet en wat het kost. Dat voorkomt discussie als het traject anders loopt. Laat de klant de opdracht vóór de start bevestigen. Leg wijzigingen in de opdracht ook vast.`,tags:['opdrachtbevestiging','vergoeding','dossier'],bron:''},
 {id:'psx-011',thema:'praktijk-software',vraag:'Wat doe ik als de opdracht tijdens het traject verandert?',antwoord:`Leg de wijziging schriftelijk vast en laat de klant akkoord geven. Pas zo nodig de vergoedingsafspraak aan. Een voorbeeld is een aankoop die overgaat in een oversluiting. Het dossier moet de nieuwe opdracht weerspiegelen.`,tags:['opdracht','wijziging','vastlegging'],bron:''},
 {id:'psx-012',thema:'praktijk-software',vraag:'Hoe richt ik een dossier in bij twee aanvragers met verschillende adressen?',antwoord:`Registreer beide aanvragers met hun eigen adres en gegevens. Noteer wie na aankoop waar gaat wonen. Dat is relevant voor eigen-woningregeling en verzekeringen. Controleer of de stukken bij de juiste persoon horen.`,tags:['dossier','aanvragers','adres'],bron:''},
 {id:'psx-013',thema:'praktijk-software',vraag:'Wat vraag ik extra bij een klant met een eerdere scheiding?',antwoord:`Vraag om het echtscheidingsconvenant en eventuele beschikking. Kijk naar alimentatie, verdeling van de woning en ontslag uit hoofdelijke aansprakelijkheid. Controleer of de oude hypotheek is afgewikkeld. Leg ontbrekende stukken vast als openstaand punt.`,tags:['scheiding','convenant','intake'],bron:''},
 {id:'psx-014',thema:'praktijk-software',vraag:'Hoe ga ik om met een klant die een tolk meeneemt?',antwoord:`Leg vast wie tolkt en in welke taal. Controleer extra goed of de klant de kern begrijpt, bijvoorbeeld door terug te vragen. Wees voorzichtig met een familielid als tolk bij gevoelige onderwerpen. Noteer dit in het dossier.`,tags:['intake','tolk','begrip'],bron:''},
 {id:'psx-015',thema:'praktijk-software',vraag:'Wat doe ik als de klant geen e-mailadres wil gebruiken?',antwoord:`Maak afspraken over een ander communicatiekanaal, zoals post of een klantportaal. Leg dit vast. Zorg dat informatieplichten toch tijdig worden nagekomen. Houd rekening met langere doorlooptijden.`,tags:['communicatie','klantportaal','dossier'],bron:''},
 {id:'psx-016',thema:'praktijk-software',vraag:'Hoe controleer ik of een identiteitsbewijs geldig is?',antwoord:`Controleer geldigheidsdatum, foto, echtheidskenmerken en gegevens. Vergelijk de gegevens met andere stukken in het dossier. Gebruik waar mogelijk een verificatiedienst. Leg vast hoe en wanneer je de controle deed.`,tags:['identificatie','legitimatie','controle'],bron:'Wwft'},
 {id:'psx-017',thema:'praktijk-software',vraag:'Wat doe ik als het identiteitsbewijs verloopt tijdens het traject?',antwoord:`Vraag tijdig een nieuw geldig document. Geldverstrekkers en notaris eisen meestal een geldig identiteitsbewijs bij aanvraag en passeren. Bewaak de geldigheidsdatum in je planning. Controleer de voorwaarden van de geldverstrekker.`,tags:['identificatie','termijnen','passeren'],bron:''},
 {id:'psx-018',thema:'praktijk-software',vraag:'Wanneer is een klant een PEP en wat betekent dat voor mijn dossier?',antwoord:`Een politiek prominent persoon vraagt verscherpt cliëntenonderzoek onder de Wwft, als je zelf onder de Wwft valt. Ook de geldverstrekker vraagt hiernaar. Stel de vraag standaard in de intake. Leg antwoord en eventuele extra controles vast.`,tags:['pep','wwft','intake'],bron:'Wwft'},
 {id:'psx-019',thema:'praktijk-software',vraag:'Hoe ga ik om met herkomst van eigen geld?',antwoord:`Vraag hoe het geld is opgebouwd en vraag bewijs, zoals afschriften of een schenkingsakte. Geldverstrekker en notaris stellen hier vaak vragen over. Grote of ongebruikelijke stortingen vragen extra toelichting. Leg de onderbouwing vast.`,tags:['eigen-middelen','herkomst','wwft'],bron:'Wwft'},
 {id:'psx-020',thema:'praktijk-software',vraag:'Hoe leg ik een schenking voor de woning vast in het dossier?',antwoord:`Bewaar de schenkingsakte of schriftelijke schenkingsovereenkomst en het betalingsbewijs. Noteer schenker, bedrag, datum en doel. Wijs de klant op aangifteplicht en fiscale voorwaarden. Verwijs voor actuele vrijstellingen naar de Belastingdienst.`,tags:['schenking','eigen-middelen','vastlegging'],bron:'Belastingdienst'},
 {id:'psx-021',thema:'praktijk-software',vraag:'Wat doe ik als een klant een lening van familie wil inbrengen?',antwoord:`Een familielening is geen eigen geld en telt mee in de lasten. Leg de leenovereenkomst en voorwaarden vast. Controleer hoe de geldverstrekker ermee omgaat. Wijs bij gebruik voor de eigen woning op de fiscale voorwaarden.`,tags:['familielening','eigen-middelen','acceptatie'],bron:'Belastingdienst'},
 {id:'psx-022',thema:'praktijk-software',vraag:'Welke vragen stel ik over toekomstplannen tijdens de intake?',antwoord:`Vraag naar gezinsuitbreiding, minder werken, studie, carrièrewisseling en verhuisplannen. Vraag ook naar wensen rond pensioen en aflossen. Leg de antwoorden vast. Gebruik ze bij de keuze voor looptijd, rentevaste periode en buffers.`,tags:['toekomst','intake','klantprofiel'],bron:''},
 {id:'psx-023',thema:'praktijk-software',vraag:'Hoe ga ik om met een klant die twijfelt over samenwonen of trouwen?',antwoord:`Bespreek de gevolgen voor eigendom, hoofdelijke aansprakelijkheid en nabestaanden. Leg vast welke situatie geldt bij aanvraag. Verwijs voor vermogensrechtelijke afspraken naar de notaris. Noteer dat je dit hebt besproken.`,tags:['samenwonen','huwelijk','notaris'],bron:''},
 {id:'psx-024',thema:'praktijk-software',vraag:'Waarom vraag ik naar een samenlevingscontract?',antwoord:`Het contract regelt afspraken over eigendom en verblijfsbeding. Het is relevant voor nabestaandenrisico en verdeling bij uit elkaar gaan. Zonder contract zijn de gevolgen anders dan bij huwelijk. Leg vast of er een contract is.`,tags:['samenlevingscontract','nabestaanden','intake'],bron:''},
 {id:'psx-025',thema:'praktijk-software',vraag:'Hoe ga ik om met huwelijkse voorwaarden in het dossier?',antwoord:`Vraag een kopie of de relevante bepalingen. Kijk naar eigendom van de woning en verrekenbedingen. Bij twijfel overleg je met de notaris. Leg vast welke uitgangspunten je in het advies gebruikt.`,tags:['huwelijkse-voorwaarden','notaris','dossier'],bron:''},
 {id:'psx-026',thema:'praktijk-software',vraag:'Wat vraag ik bij een klant die een woning in het buitenland heeft?',antwoord:`Vraag naar waarde, financiering, lasten en eventuele huurinkomsten. Dit kan meetellen in de lasten en in box 3. Geldverstrekkers gaan verschillend met buitenlandse bezittingen om. Controleer de voorwaarden van de geldverstrekker.`,tags:['buitenland','vermogen','acceptatie'],bron:''},
 {id:'psx-027',thema:'praktijk-software',vraag:'Hoe registreer ik studieschuld in het dossier?',antwoord:`Leg het oorspronkelijke bedrag, de huidige stand en het terugbetaalregime vast. Vraag het overzicht van DUO. Het stelsel bepaalt hoe de schuld meetelt in de toets. Controleer de voorwaarden van de geldverstrekker.`,tags:['studieschuld','duo','lasten'],bron:'DUO'},
 {id:'psx-028',thema:'praktijk-software',vraag:'Wat doe ik als een klant een lopend krediet niet meldt?',antwoord:`Een BKR-toets of bankafschrift kan dit alsnog laten zien. Bespreek het verschil en pas de berekening aan. Leg vast dat informatie aanvankelijk ontbrak. Bij opzet om gegevens te verzwijgen kun je overwegen de opdracht niet voort te zetten.`,tags:['krediet','bkr','verzwijgen'],bron:'BKR'},
 {id:'psx-029',thema:'praktijk-software',vraag:'Hoe ga ik om met een private lease contract in de intake?',antwoord:`Private lease wordt sinds enige tijd bij BKR geregistreerd en telt mee in de leenruimte. Vraag het contract en de maandtermijn. Controleer hoe de geldverstrekker het meeneemt. Leg dit vast in de inventarisatie.`,tags:['private-lease','bkr','lasten'],bron:'BKR'},
 {id:'psx-030',thema:'praktijk-software',vraag:'Welke gegevens vraag ik van de huidige woning bij doorstromers?',antwoord:`Vraag de actuele hypotheekgegevens, leningdelen, rentevaste periodes en eventuele boeterente. Vraag ook WOZ-waarde, verwachte verkoopprijs en eventuele EWR-gegevens. Leg vast of de woning al verkocht is. Dit bepaalt overbrugging en meeneemregeling.`,tags:['doorstromer','huidige-woning','intake'],bron:''},
 {id:'psx-031',thema:'praktijk-software',vraag:'Hoe documenteer ik de meeneemregeling van een bestaande hypotheek?',antwoord:`Leg de voorwaarden van de huidige geldverstrekker vast, zoals termijn en welke leningdelen meegaan. Noteer de rente en resterende rentevaste periode. Vergelijk met een nieuwe financiering. Leg de afweging en klantkeuze vast.`,tags:['meeneemregeling','doorstromer','vastlegging'],bron:''},
 {id:'psx-032',thema:'praktijk-software',vraag:'Wat leg ik vast over de eigenwoningreserve?',antwoord:`Leg verkoopprijs, eigenwoningschuld en eventuele eerdere reserve vast. Een EWR vervalt na 3 jaar. Noteer hoe de reserve in de nieuwe financiering is verwerkt. Bij twijfel adviseer je fiscale controle.`,tags:['ewr','fiscaal','doorstromer'],bron:'Wet IB 2001'},
 {id:'psx-033',thema:'praktijk-software',vraag:'Hoe registreer ik een restschuld uit de regeling 2012 tot 2017?',antwoord:`Leg vast dat de restschuld ontstond tussen 29-10-2012 en 31-12-2017. De rente is dan maximaal 15 jaar aftrekbaar. Noteer startdatum en resterende looptijd. Vraag stukken van de verkoop en de restschuldlening.`,tags:['restschuld','fiscaal','dossier'],bron:'Wet IB 2001'},
 {id:'psx-034',thema:'praktijk-software',vraag:'Wat vraag ik bij een klant die al eerder een hypotheek had vóór 2013?',antwoord:`Vraag naar de eigenwoningschuld per 31-12-2012 en de leningdelen. Dit bepaalt het overgangsrecht. Leg de bewijsstukken vast. Bij meenemen of oversluiten is dit van groot belang.`,tags:['overgangsrecht','2013','fiscaal'],bron:'Wet IB 2001'},
 {id:'psx-035',thema:'praktijk-software',vraag:'Hoe ga ik om met een aanvrager die nog in de proeftijd zit?',antwoord:`Vraag naar de duur van de proeftijd en de afspraken over vaste aanstelling. Geldverstrekkers gaan verschillend om met inkomen in de proeftijd. Een werkgeversverklaring kan hier uitsluitsel geven. Controleer de voorwaarden van de geldverstrekker.`,tags:['proeftijd','inkomen','acceptatie'],bron:''},
 {id:'psx-036',thema:'praktijk-software',vraag:'Waarom noteer ik de geboortedatum van alle aanvragers zo nauwkeurig?',antwoord:`Leeftijd bepaalt de AOW-datum, looptijd en toetsing van pensioeninkomen. Een fout leidt tot verkeerde berekeningen en een afwijkende HDN-aanvraag. Controleer de datum met het identiteitsbewijs. Zo voorkom je afwijzing of vertraging.`,tags:['geboortedatum','aow','data'],bron:''},
 {id:'psx-037',thema:'praktijk-software',vraag:'Hoe ga ik om met inwonende kinderen of ouders in de woning?',antwoord:`Leg de woonsituatie vast in de inventarisatie. Dit is relevant voor verzekeringen, budget en eventuele huurinkomsten. Inkomsten van inwonenden tellen meestal niet mee. Controleer de voorwaarden van de geldverstrekker.`,tags:['woonsituatie','inwonend','budget'],bron:''},
 {id:'psx-038',thema:'praktijk-software',vraag:'Hoe leg ik vast dat een klant mijn advies niet opvolgt?',antwoord:`Noteer het advies, de keuze van de klant en de reden. Benoem de risicos die je hebt besproken. Laat de klant de afwijkende keuze bevestigen. Overweeg of je de opdracht nog verantwoord kunt uitvoeren.`,tags:['afwijkende-keuze','vastlegging','advies'],bron:'Wft'},
 {id:'psx-039',thema:'praktijk-software',vraag:'Wat is het verschil tussen een klantprofiel en een inventarisatie?',antwoord:`Het klantprofiel beschrijft wie de klant is en wat hij wil. De inventarisatie bevat ook de financiële gegevens en stukken. Samen vormen ze de basis voor het advies. Houd beide actueel en gedateerd.`,tags:['klantprofiel','inventarisatie','dossier'],bron:''},
 {id:'psx-040',thema:'praktijk-software',vraag:'Hoe voorkom ik dat oude stukken in een nieuw dossier belanden?',antwoord:`Start bij een nieuw adviesmoment een nieuw dossier of een duidelijk gescheiden map. Neem alleen actuele stukken over. Datum en versienummer helpen bij het onderscheid. Controleer dit bij de interne review.`,tags:['dossier','versiebeheer','actueel'],bron:''},
 {id:'psx-041',thema:'praktijk-software',vraag:'Wat doe ik als een klant stukken via een chatapp stuurt?',antwoord:`Chatapps zijn vaak niet geschikt voor gevoelige stukken. Vraag de klant voortaan een beveiligd portaal of veilige mail te gebruiken. Sla ontvangen stukken op in het dossier en verwijder ze van het toestel. Leg je beleid vast.`,tags:['beveiliging','avg','communicatie'],bron:'AVG'},
 {id:'psx-042',thema:'praktijk-software',vraag:'Hoe lang bewaar ik stukken van een klant die afhaakt?',antwoord:`Bepaal dit in je bewaarbeleid en houd rekening met de AVG. Bewaar niet langer dan nodig voor het doel, zoals klachtafhandeling of wettelijke plichten. Leg de gekozen termijn en reden vast. Vernietig stukken daarna aantoonbaar.`,tags:['bewaartermijn','avg','afgehaakt'],bron:'AVG'},
 {id:'psx-043',thema:'praktijk-software',vraag:'Wat leg ik vast bij een adviesgesprek dat niet doorgaat?',antwoord:`Noteer wat er besproken is en waarom het traject stopte. Leg vast welke stukken je hebt ontvangen. Stuur zo nodig een afrondingsbericht. Dat beschermt je bij latere vragen of klachten.`,tags:['afgebroken','vastlegging','dossier'],bron:''},
 {id:'psx-044',thema:'praktijk-software',vraag:'Hoe controleer ik de volledigheid van een dossier vóór het advies?',antwoord:`Werk met een checklist per type traject. Controleer identiteit, inkomen, woning, verplichtingen, wensen en risicos. Markeer ontbrekende stukken als openstaand. Geef pas definitief advies als de kern compleet is.`,tags:['volledigheid','checklist','dossier'],bron:''},
 {id:'psx-045',thema:'praktijk-software',vraag:'Hoe ga ik om met een klant met een betalingsachterstand in het verleden?',antwoord:`Vraag een BKR-overzicht en de toelichting van de klant. Leg vast wat er speelde en hoe het is opgelost. Geldverstrekkers verschillen in hun beoordeling. Controleer de voorwaarden van de geldverstrekker voordat je verwachtingen schept.`,tags:['bkr','achterstand','acceptatie'],bron:'BKR'},
 {id:'psx-046',thema:'praktijk-software',vraag:'Wat vraag ik bij een klant met een eigen bedrijf naast loondienst?',antwoord:`Vraag naast loonstukken ook jaarcijfers of aangiftes van de onderneming. Bepaal welk inkomen meetelt en hoe stabiel het is. Let op verplichtingen van het bedrijf. Leg de opbouw van het toetsinkomen vast.`,tags:['ondernemer','loondienst','inkomen'],bron:''},
 {id:'psx-047',thema:'praktijk-software',vraag:'Hoe registreer ik vermogen dat vastzit, zoals een spaarrekening met looptijd?',antwoord:`Leg vast wanneer het geld vrijkomt. Vermogen dat niet tijdig beschikbaar is kun je niet als eigen inbreng bij passeren gebruiken. Noteer eventuele opnamekosten. Bespreek alternatieven met de klant.`,tags:['vermogen','eigen-middelen','beschikbaarheid'],bron:''},
 {id:'psx-048',thema:'praktijk-software',vraag:'Wanneer schakel ik een specialist in tijdens de intake?',antwoord:`Doe dat als het dossier buiten je eigen deskundigheid valt. Denk aan complexe fiscale situaties, internationaal inkomen of bedrijfsoverdracht. Leg vast wie je inschakelt en waarvoor. Je blijft zelf verantwoordelijk voor je eigen advies.`,tags:['specialist','deskundigheid','intake'],bron:'Wft'},
 {id:'psx-049',thema:'praktijk-software',vraag:'Hoe leg ik vast dat de klant de dienstverleningsinformatie heeft ontvangen?',antwoord:`Stuur de informatie vóór of uiterlijk bij de start van de dienstverlening. Bewaar een bewijs van verzending of akkoord. Een vinkje in de software met datum kan volstaan als het te herleiden is. Bewaar de versie die de klant kreeg.`,tags:['dienstverlening','informatieplicht','vastlegging'],bron:'Wft'},
 {id:'psx-050',thema:'praktijk-software',vraag:'Wat noteer ik als een klant tijdens het traject van geldverstrekker wil wisselen?',antwoord:`Leg de reden en het moment van de wissel vast. Noteer de gevolgen, zoals nieuwe taxatie-eisen, kosten of termijnen. Controleer of de ontbindingsdatum nog haalbaar is. Laat de klant de keuze bevestigen.`,tags:['geldverstrekker','wissel','vastlegging'],bron:''},
 {id:'psx-051',thema:'praktijk-software',vraag:'Wat doe ik als de werkgeversverklaring niet aansluit op de salarisstrook?',antwoord:`Zoek eerst de oorzaak, zoals een recente loonsverhoging, een andere periode of een rekenfout. Vraag zo nodig een gecorrigeerde verklaring of een toelichting van de werkgever. Stuur geen tegenstrijdige stukken zonder uitleg in. Leg je controle vast.`,tags:['werkgeversverklaring','salarisstrook','controle'],bron:''},
 {id:'psx-052',thema:'praktijk-software',vraag:'Mag een aanvrager zelf zijn werkgeversverklaring ondertekenen?',antwoord:`Bij een DGA of familiebedrijf is dat een bekend risico. Geldverstrekkers stellen dan vaak extra eisen of behandelen het inkomen als ondernemersinkomen. Vraag naar de verhouding met de werkgever. Controleer de voorwaarden van de geldverstrekker.`,tags:['werkgeversverklaring','dga','familiebedrijf'],bron:''},
 {id:'psx-053',thema:'praktijk-software',vraag:'Welke velden op een werkgeversverklaring worden vaak vergeten?',antwoord:`Veelvoorkomend zijn een ontbrekende intentieverklaring, onvolledige vaste toeslagen of een lege handtekening. Ook een ontbrekende datum of stempel geeft problemen. Controleer het formulier altijd regel voor regel. Gebruik het actuele model dat de geldverstrekker accepteert.`,tags:['werkgeversverklaring','fouten','controle'],bron:''},
 {id:'psx-054',thema:'praktijk-software',vraag:'Wat betekent een intentieverklaring bij een tijdelijk contract?',antwoord:`De werkgever verklaart dan dat het dienstverband bij gelijke omstandigheden wordt voortgezet. Daarmee kan inkomen uit een tijdelijk contract als vast inkomen meetellen. Ontbreekt de verklaring, dan gelden andere routes zoals IBL. Controleer de voorwaarden van de geldverstrekker.`,tags:['intentieverklaring','tijdelijk-contract','inkomen'],bron:''},
 {id:'psx-055',thema:'praktijk-software',vraag:'Wat doe ik als het UWV-verzekeringsbericht onvolledig is?',antwoord:`Bekijk welke perioden of werkgevers ontbreken. Soms ligt het aan een vertraagde aangifte door de werkgever. Een IBL-berekening kan dan een vertekend beeld geven. Overweeg een andere inkomensroute en leg dit vast.`,tags:['uwv','verzekeringsbericht','ibl'],bron:'UWV'},
 {id:'psx-056',thema:'praktijk-software',vraag:'Waarom kan een IBL-berekening lager uitvallen dan verwacht?',antwoord:`De berekening kijkt naar inkomen over een langere periode. Recente loonstijgingen tellen dan maar deels mee. Ook onbetaald verlof of lagere uren drukken het resultaat. Bespreek dit vooraf met de klant.`,tags:['ibl','berekening','inkomen'],bron:''},
 {id:'psx-057',thema:'praktijk-software',vraag:'Hoe ga ik om met een loonsverhoging die net is ingegaan?',antwoord:`Leg bewijs vast, zoals een brief van de werkgever en een nieuwe salarisstrook. Een werkgeversverklaring geeft het actuele inkomen weer. IBL neemt de verhoging mogelijk maar beperkt mee. Kies de route bewust en noteer waarom.`,tags:['loonsverhoging','inkomen','ibl'],bron:''},
 {id:'psx-058',thema:'praktijk-software',vraag:'Hoe controleer ik een salarisstrook op opvallende zaken?',antwoord:`Kijk naar naam, werkgever, periode en loonheffingsnummer. Controleer of bruto, inhoudingen en netto logisch samenhangen. Vergelijk met bankafschriften. Afwijkingen bespreek je met de klant en leg je vast.`,tags:['salarisstrook','controle','fraude'],bron:''},
 {id:'psx-059',thema:'praktijk-software',vraag:'Waarom vergelijk ik inkomensstukken met bankafschriften?',antwoord:`Het netto salaris moet terugkomen op de rekening. Zo vang je fouten of vervalsingen op. Ook zie je lasten die niet zijn gemeld. Leg vast dat je deze vergelijking hebt gedaan.`,tags:['bankafschrift','controle','inkomen'],bron:''},
 {id:'psx-060',thema:'praktijk-software',vraag:'Hoe ga ik om met inkomen uit ploegentoeslag of onregelmatigheidstoeslag?',antwoord:`Het hangt af van of de toeslag structureel is. Een werkgeversverklaring of IBL kan dit verwerken. Vraag naar de duur en zekerheid van het rooster. Controleer de voorwaarden van de geldverstrekker.`,tags:['toeslagen','onregelmatigheid','inkomen'],bron:''},
 {id:'psx-061',thema:'praktijk-software',vraag:'Hoe behandel ik een eindejaarsuitkering of dertiende maand?',antwoord:`Bepaal of het vast en onvoorwaardelijk is. Een vaste uitkering kan meetellen, een variabele bonus vaak niet of beperkt. Vraag de bepaling in arbeidsovereenkomst of cao. Leg vast hoe het in het toetsinkomen is verwerkt.`,tags:['dertiende-maand','eindejaarsuitkering','inkomen'],bron:''},
 {id:'psx-062',thema:'praktijk-software',vraag:'Hoe ga ik om met variabel inkomen zoals provisie of bonus?',antwoord:`Variabel inkomen telt vaak alleen mee als het over meerdere jaren aantoonbaar is. Vraag jaaropgaven en een toelichting van de werkgever. IBL kan dit soms beter laten zien. Controleer de voorwaarden van de geldverstrekker.`,tags:['variabel-inkomen','bonus','provisie'],bron:''},
 {id:'psx-063',thema:'praktijk-software',vraag:'Wat vraag ik bij een flexwerker zonder vaste uren?',antwoord:`Vraag jaaropgaven, het UWV-verzekeringsbericht en het arbeidscontract. Vaak is IBL of een flexroute de aangewezen weg. Kijk naar de stabiliteit over meerdere jaren. Leg vast welke route je kiest en waarom.`,tags:['flexwerker','oproepkracht','inkomen'],bron:''},
 {id:'psx-064',thema:'praktijk-software',vraag:'Hoe ga ik om met inkomen uit het buitenland?',antwoord:`Geldverstrekkers stellen hier extra eisen aan, zoals vertaalde stukken en bewijs van belastingafdracht. Valutarisico en fiscale behandeling spelen mee. Niet elke geldverstrekker accepteert dit. Controleer de voorwaarden en leg vast wat je hebt geverifieerd.`,tags:['buitenland','inkomen','acceptatie'],bron:''},
 {id:'psx-065',thema:'praktijk-software',vraag:'Welke stukken vraag ik bij een uitkering als inkomen?',antwoord:`Vraag de toekenningsbeschikking en een recent betaaloverzicht. Kijk naar duur en voorwaarden van de uitkering. Een tijdelijke uitkering telt vaak niet of beperkt mee. Controleer de voorwaarden van de geldverstrekker.`,tags:['uitkering','inkomen','beschikking'],bron:'UWV'},
 {id:'psx-066',thema:'praktijk-software',vraag:'Hoe ga ik om met partneralimentatie als inkomen?',antwoord:`Vraag het convenant of de beschikking en bewijs van ontvangst. Let op de resterende duur van de alimentatie. Geldverstrekkers rekenen alleen mee als de duur voldoende is. Controleer de voorwaarden van de geldverstrekker.`,tags:['alimentatie','inkomen','convenant'],bron:''},
 {id:'psx-067',thema:'praktijk-software',vraag:'Hoe verwerk ik te betalen partneralimentatie in de toets?',antwoord:`Te betalen partneralimentatie verlaagt de leenruimte. De verwerking verschilt per geldverstrekker. Vraag de actuele bedragen en de looptijd. Leg vast hoe je dit hebt meegenomen.`,tags:['alimentatie','lasten','leenruimte'],bron:''},
 {id:'psx-068',thema:'praktijk-software',vraag:'Welke inkomensstukken vraag ik bij pensioen?',antwoord:`Vraag recente uitkeringsspecificaties van AOW en aanvullend pensioen. Kijk ook naar het pensioenoverzicht voor nabestaandenpensioen. Controleer of het inkomen levenslang is. Leg de opbouw van het toetsinkomen vast.`,tags:['pensioen','aow','inkomen'],bron:''},
 {id:'psx-069',thema:'praktijk-software',vraag:'Hoe ga ik om met een aanvrager die binnen tien jaar met pensioen gaat?',antwoord:`Het inkomen na pensionering kan de toets beïnvloeden. Vraag een pensioenoverzicht en bereken de lasten na de AOW-datum. Bespreek de gevolgen met de klant. Leg de berekening en afweging vast.`,tags:['pensioen','aow-datum','toetsing'],bron:'Nibud'},
 {id:'psx-070',thema:'praktijk-software',vraag:'Wat doe ik als een klant geen recent pensioenoverzicht heeft?',antwoord:`Laat de klant het overzicht ophalen via mijnpensioenoverzicht.nl of de pensioenuitvoerder. Gebruik geen oude gegevens zonder controle. Noteer de datum van het overzicht. Zo blijft de berekening te volgen.`,tags:['pensioenoverzicht','actualiteit','inkomen'],bron:''},
 {id:'psx-071',thema:'praktijk-software',vraag:'Hoe ga ik om met een arbeidsmarktscan bij een flexibel inkomen?',antwoord:`Een arbeidsmarktscan beoordeelt de verdiencapaciteit op basis van opleiding en ervaring. Sommige geldverstrekkers accepteren dit als inkomensbewijs. Let op geldigheid en voorwaarden van de scan. Controleer welke geldverstrekker hem accepteert.`,tags:['arbeidsmarktscan','flex','inkomen'],bron:''},
 {id:'psx-072',thema:'praktijk-software',vraag:'Hoe controleer ik een inkomensverklaring van een ondernemer?',antwoord:`Controleer of de verklaring is opgesteld door een erkende rekenexpert of het geaccepteerde type deskundige. Kijk of de onderliggende cijfers aansluiten op aangiftes. Let op bijzondere posten. Controleer de voorwaarden van de geldverstrekker.`,tags:['ondernemer','inkomensverklaring','rekenexpert'],bron:''},
 {id:'psx-073',thema:'praktijk-software',vraag:'Wat zijn veelgemaakte fouten bij inkomensstukken van ondernemers?',antwoord:`Veelvoorkomend zijn ontbrekende jaren, cijfers die niet aansluiten op de aangifte en een negatieve trend zonder toelichting. Ook ontbrekende privé-opnames bij een DGA vallen op. Controleer het pakket voor indiening. Leg je beoordeling vast.`,tags:['ondernemer','fouten','jaarcijfers'],bron:''},
 {id:'psx-074',thema:'praktijk-software',vraag:'Hoe ga ik om met een startende ondernemer zonder jaarcijfers?',antwoord:`Veel geldverstrekkers vragen een minimale periode aan cijfers. Sommige accepteren een prognose of een andere route. Bespreek realistisch wat haalbaar is. Controleer de voorwaarden van de geldverstrekker.`,tags:['starter','ondernemer','jaarcijfers'],bron:''},
 {id:'psx-075',thema:'praktijk-software',vraag:'Waar let ik op bij een DGA met een laag salaris en hoge winst?',antwoord:`Geldverstrekkers kijken vaak naar wat de DGA structureel uit de bv kan halen. De beoordeling verschilt per partij. Vraag jaarrekeningen en een inkomensverklaring. Leg vast hoe het toetsinkomen is bepaald.`,tags:['dga','winst','inkomen'],bron:''},
 {id:'psx-076',thema:'praktijk-software',vraag:'Hoe controleer ik een jaaropgave?',antwoord:`Controleer naam, werkgever, jaar en fiscaal loon. Vergelijk met de salarisstroken en het UWV-bericht. Let op grote afwijkingen tussen jaren. Vraag een toelichting bij onverklaarbare verschillen.`,tags:['jaaropgave','controle','inkomen'],bron:''},
 {id:'psx-077',thema:'praktijk-software',vraag:'Hoe ga ik om met een klant in loondienst met een nevenactiviteit als zzp-er?',antwoord:`Het loondienstinkomen kan apart worden beoordeeld. Het zzp-inkomen telt alleen mee als het aantoonbaar en stabiel is. Vraag aangiftes en jaarcijfers. Controleer de voorwaarden van de geldverstrekker.`,tags:['zzp','nevenactiviteit','inkomen'],bron:''},
 {id:'psx-078',thema:'praktijk-software',vraag:'Wat leg ik vast als ik twijfel aan de echtheid van een inkomensstuk?',antwoord:`Noteer wat je opviel en welke controle je deed. Vraag om een aanvullend of origineel stuk. Dien geen stuk in waaraan je twijfelt. Volg je interne fraudeprocedure en leg je beslissing vast.`,tags:['fraude','echtheid','vastlegging'],bron:''},
 {id:'psx-079',thema:'praktijk-software',vraag:'Hoe recent moet een UWV-verzekeringsbericht zijn?',antwoord:`Dat verschilt per geldverstrekker en per route. Vraag het bericht zo laat mogelijk op voor indiening. Noteer de datum van downloaden. Controleer de voorwaarden van de geldverstrekker.`,tags:['uwv','actualiteit','termijnen'],bron:'UWV'},
 {id:'psx-080',thema:'praktijk-software',vraag:'Hoe ga ik om met inkomen tijdens ouderschapsverlof?',antwoord:`Een tijdelijke daling kan het inkomen in stukken of IBL drukken. Een werkgeversverklaring kan het reguliere inkomen tonen. Vraag naar duur van het verlof. Leg vast welke route je kiest.`,tags:['ouderschapsverlof','inkomen','ibl'],bron:''},
 {id:'psx-081',thema:'praktijk-software',vraag:'Wat doe ik als een aanvrager ziek is tijdens het traject?',antwoord:`Vraag naar de duur en verwachte terugkeer. Geldverstrekkers en verzekeraars stellen vragen over arbeidsongeschiktheid. Wees eerlijk in de aanvraag. Controleer de voorwaarden van de geldverstrekker en verzekeraar.`,tags:['ziekte','arbeidsongeschiktheid','aanvraag'],bron:''},
 {id:'psx-082',thema:'praktijk-software',vraag:'Waarom moet ik bij taxatie de juiste opdrachtgever en geldverstrekker vermelden?',antwoord:`Het rapport moet geschikt zijn voor de financiering bij die partij. Een rapport voor een andere geldverstrekker wordt vaak niet zomaar geaccepteerd. Controleer de gegevens vóór de opdracht. Wijzigingen achteraf kosten tijd en geld.`,tags:['taxatie','opdracht','geldverstrekker'],bron:''},
 {id:'psx-083',thema:'praktijk-software',vraag:'Wat doe ik als een taxatierapport fouten bevat?',antwoord:`Meld de fouten aan de taxateur en vraag een correctie. Denk aan een verkeerd adres, oppervlakte of naam. Een fout rapport kan de validatie blokkeren. Leg het verloop vast in het dossier.`,tags:['taxatie','fouten','correctie'],bron:''},
 {id:'psx-084',thema:'praktijk-software',vraag:'Hoe ga ik om met een taxatie bij verbouwing?',antwoord:`Laat de waarde na verbouwing bepalen op basis van een verbouwingsspecificatie. De taxateur moet de specificatie hebben. Het bouwdepot sluit aan op die specificatie. Controleer de voorwaarden van de geldverstrekker.`,tags:['taxatie','verbouwing','bouwdepot'],bron:''},
 {id:'psx-085',thema:'praktijk-software',vraag:'Welke verbouwingsspecificatie heeft de taxateur nodig?',antwoord:`Een overzicht van werkzaamheden met bedragen, liefst onderbouwd met offertes. Maak onderscheid tussen waardeverhogende en andere kosten. Een vage specificatie leidt tot discussie. Bewaar de specificatie in het dossier.`,tags:['verbouwingsspecificatie','taxatie','offertes'],bron:''},
 {id:'psx-086',thema:'praktijk-software',vraag:'Wanneer is een taxatierapport te oud?',antwoord:`Geldverstrekkers hanteren een maximale ouderdom van het rapport. Die termijn verschilt per partij. Bij vertraging kan een nieuw rapport nodig zijn. Controleer de voorwaarden van de geldverstrekker.`,tags:['taxatie','geldigheid','termijnen'],bron:''},
 {id:'psx-087',thema:'praktijk-software',vraag:'Wat zegt een energielabel in het taxatierapport over de leenruimte?',antwoord:`Het energielabel bepaalt een extra leenruimte op grond van de leennormen. Bij aankoop is die €0 voor E/F/G, €5.000 voor C/D en €10.000 voor A/B. Voor A+/A++ geldt €20.000, voor A+++ €25.000 en voor A++++ €30.000. Met energieprestatiegarantie bij A++++ is dat €40.000.`,tags:['energielabel','leenruimte','taxatie'],bron:'Nibud'},
 {id:'psx-088',thema:'praktijk-software',vraag:'Wat doe ik als het energielabel ontbreekt of verouderd is?',antwoord:`Zonder geregistreerd label kan de extra leenruimte anders uitvallen. Bij verduurzaming geldt voor een onbekend label €10.000. Vraag de klant of verkoper het label te laten vastleggen. Controleer hoe de geldverstrekker ermee omgaat.`,tags:['energielabel','onbekend','verduurzaming'],bron:'Nibud'},
 {id:'psx-089',thema:'praktijk-software',vraag:'Hoe hoog is de verduurzamingsruimte per energielabel?',antwoord:`Volgens de leennormen is dat €20.000 bij E/F/G, €15.000 bij C/D en €10.000 bij A/B en A+/A++. Bij A+++ en beter is het €0. Bij een onbekend label geldt €10.000. Leg vast welke maatregelen de klant wil nemen.`,tags:['verduurzaming','energielabel','leenruimte'],bron:'Nibud'},
 {id:'psx-090',thema:'praktijk-software',vraag:'Mag ik energielabel-leenruimte bij aankoop en verduurzaming optellen?',antwoord:`De normen kennen aparte bedragen voor aankoop en verduurzaming. Hoe ze samen worden toegepast, hangt af van het beleid van de geldverstrekker. Controleer de voorwaarden van de geldverstrekker. Leg de gebruikte opbouw vast.`,tags:['energielabel','verduurzaming','leennormen'],bron:'Nibud'},
 {id:'psx-091',thema:'praktijk-software',vraag:'Wat controleer ik in de bouwkundige paragraaf van een taxatierapport?',antwoord:`Kijk naar opgemerkte gebreken en geschatte herstelkosten. Soms eist de geldverstrekker herstel binnen een termijn of een bouwdepot. Bespreek de bevindingen met de klant. Leg vast welke actie je hebt afgesproken.`,tags:['taxatie','bouwkundig','gebreken'],bron:''},
 {id:'psx-092',thema:'praktijk-software',vraag:'Hoe ga ik om met een erfpachtwoning in de taxatie?',antwoord:`De taxateur moet de erfpachtvoorwaarden en canon meenemen. Vraag de akte en de actuele voorwaarden op. Canon telt mee in de lasten. Controleer hoe de geldverstrekker erfpacht beoordeelt.`,tags:['erfpacht','canon','taxatie'],bron:''},
 {id:'psx-093',thema:'praktijk-software',vraag:'Wat doe ik als de taxateur de woning niet van binnen kon bekijken?',antwoord:`Een rapport zonder inpandige opname wordt vaak niet geaccepteerd voor financiering. Vraag naar de reden en plan een nieuwe opname. Leg vertraging vast en bewaak de termijnen. Controleer de voorwaarden van de geldverstrekker.`,tags:['taxatie','opname','termijnen'],bron:''},
 {id:'psx-094',thema:'praktijk-software',vraag:'Wanneer is een desktoptaxatie of modelwaarde mogelijk?',antwoord:`Sommige geldverstrekkers accepteren in bepaalde situaties een modelmatige waardebepaling. Denk aan een lage verhouding tussen lening en waarde. De voorwaarden verschillen sterk. Controleer de voorwaarden van de geldverstrekker.`,tags:['modelwaarde','desktoptaxatie','taxatie'],bron:''},
 {id:'psx-095',thema:'praktijk-software',vraag:'Wat is het verschil tussen marktwaarde en marktwaarde na verbouwing?',antwoord:`De marktwaarde is de huidige waarde van de woning. De marktwaarde na verbouwing gaat uit van uitgevoerde werkzaamheden volgens specificatie. De maximale lening kan op die tweede waarde zijn gebaseerd. Controleer de voorwaarden van de geldverstrekker.`,tags:['marktwaarde','verbouwing','taxatie'],bron:''},
 {id:'psx-096',thema:'praktijk-software',vraag:'Hoe voorkom ik vertraging bij de validatie van een taxatierapport?',antwoord:`Geef de taxateur volledige en juiste gegevens bij de opdracht. Lever koopovereenkomst en verbouwingsspecificatie direct mee. Controleer het rapport zodra het binnen is. Bewaak de status bij het validatie-instituut.`,tags:['validatie','taxatie','doorlooptijd'],bron:''},
 {id:'psx-097',thema:'praktijk-software',vraag:'Wat doe ik als de koopsom inclusief roerende zaken is?',antwoord:`Roerende zaken horen niet in de waarde van de woning. Ze kunnen gevolgen hebben voor de overdrachtsbelasting en de fiscale financiering. Vraag de lijst met roerende zaken. Overleg met de notaris over de verwerking.`,tags:['roerende-zaken','koopsom','notaris'],bron:''},
 {id:'psx-098',thema:'praktijk-software',vraag:'Hoe ga ik om met een nieuwbouwwoning zonder taxatie?',antwoord:`Bij nieuwbouw geldt vaak de koop-aanneemsom plus meerwerk als basis. Sommige geldverstrekkers vragen toch een taxatie. Controleer de voorwaarden van de geldverstrekker. Leg de gebruikte waarde vast.`,tags:['nieuwbouw','taxatie','koop-aanneemsom'],bron:''},
 {id:'psx-099',thema:'praktijk-software',vraag:'Wat leg ik vast als de klant de woning laat taxeren vóór het bod?',antwoord:`Noteer dat de taxatie vooraf is gedaan en voor welke geldverstrekker. Let erop dat het rapport bij aanvraag nog geldig is. Bespreek dat een andere geldverstrekker mogelijk een nieuw rapport vraagt. Leg de kosten en afspraken vast.`,tags:['taxatie','vooraf','bod'],bron:''},
 {id:'psx-100',thema:'praktijk-software',vraag:'Hoe ga ik om met een appartement en de VvE in het dossier?',antwoord:`Vraag de stukken van de VvE, zoals splitsingsakte, notulen en meerjarenonderhoudsplan. Kijk naar de bijdrage en eventueel achterstallig onderhoud. De VvE-bijdrage hoort in het budget. Controleer de voorwaarden van de geldverstrekker.`,tags:['vve','appartement','dossier'],bron:''},
 {id:'psx-101',thema:'praktijk-software',vraag:'Wat is het verschil tussen een HDN-aanvraag en een losse e-mail aan de geldverstrekker?',antwoord:`Een HDN-bericht is gestructureerd en wordt automatisch verwerkt. Een e-mail moet handmatig worden overgenomen. Dat geeft meer kans op fouten en vertraging. Gebruik waar mogelijk het HDN-berichtenverkeer.`,tags:['hdn','berichtenverkeer','aanvraag'],bron:'HDN'},
 {id:'psx-102',thema:'praktijk-software',vraag:'Wat doe ik als een HDN-bericht wordt afgekeurd door een validatiefout?',antwoord:`Lees de foutmelding goed en zoek het veld dat niet klopt. Vaak gaat het om een ontbrekend verplicht veld of een onjuist formaat. Corrigeer in de adviessoftware en verstuur opnieuw. Noteer de fout om herhaling te voorkomen.`,tags:['hdn','validatiefout','software'],bron:'HDN'},
 {id:'psx-103',thema:'praktijk-software',vraag:'Waarom moet ik een HDN-aanvraag niet te vroeg versturen?',antwoord:`Een aanvraag met voorlopige gegevens leidt tot een offerte die later moet worden aangepast. Dat kost tijd en kan extra vragen opleveren. Controleer eerst inkomen, woning en wensen. Verstuur pas als de kern vaststaat.`,tags:['hdn','timing','aanvraag'],bron:''},
 {id:'psx-104',thema:'praktijk-software',vraag:'Hoe controleer ik een HDN-aanvraag vóór verzending?',antwoord:`Loop namen, geboortedata, inkomen, onderpand, leningdelen en rentevaste periodes na. Vergelijk met de stukken in het dossier. Laat bij twijfel een collega meekijken. Een fout in de aanvraag werkt door in de offerte.`,tags:['hdn','controle','vier-ogen'],bron:''},
 {id:'psx-105',thema:'praktijk-software',vraag:'Wat is een wijzigingsaanvraag via HDN?',antwoord:`Daarmee pas je een lopende aanvraag of offerte aan. Denk aan een andere rentevaste periode of leningbedrag. Niet elke wijziging is via een wijzigingsbericht mogelijk. Controleer de voorwaarden van de geldverstrekker.`,tags:['hdn','wijziging','offerte'],bron:'HDN'},
 {id:'psx-106',thema:'praktijk-software',vraag:'Hoe ga ik om met statusberichten van de geldverstrekker?',antwoord:`Statusberichten tonen de voortgang en openstaande stukken. Verwerk ze direct in je dossier en planning. Stuur ontbrekende stukken zo snel mogelijk aan. Laat de klant weten wat er nog nodig is.`,tags:['hdn','status','voortgang'],bron:'HDN'},
 {id:'psx-107',thema:'praktijk-software',vraag:'Wat doe ik als de offerte afwijkt van de aanvraag?',antwoord:`Vergelijk de offerte regel voor regel met de aanvraag. Zoek de oorzaak, zoals een aangepast bedrag of rente. Vraag zo nodig een correctie aan. Bespreek de verschillen met de klant voordat die tekent.`,tags:['offerte','controle','afwijking'],bron:''},
 {id:'psx-108',thema:'praktijk-software',vraag:'Hoe leg ik vast dat de klant de offerte heeft begrepen?',antwoord:`Bespreek de belangrijkste voorwaarden en kosten. Noteer welke punten je hebt toegelicht. Bewaar de getekende offerte en eventuele vragen van de klant. Zo kun je later aantonen dat je de offerte hebt besproken.`,tags:['offerte','uitleg','vastlegging'],bron:''},
 {id:'psx-109',thema:'praktijk-software',vraag:'Wat is een renteaanbod en hoe verschilt het van een bindende offerte?',antwoord:`Een renteaanbod is een eerste aanbod onder voorbehoud van beoordeling. De bindende offerte volgt na beoordeling van de stukken. De voorwaarden en status verschillen per geldverstrekker. Leg vast in welke fase het dossier zit.`,tags:['renteaanbod','offerte','fasen'],bron:''},
 {id:'psx-110',thema:'praktijk-software',vraag:'Hoe ga ik om met een rentewijziging tussen aanvraag en offerte?',antwoord:`De rentezekerheid hangt af van de voorwaarden van de geldverstrekker. Soms geldt de laagste rente bij passeren. Controleer de voorwaarden van de geldverstrekker. Informeer de klant over de gevolgen.`,tags:['rente','offerte','rentezekerheid'],bron:''},
 {id:'psx-111',thema:'praktijk-software',vraag:'Wat zijn veelvoorkomende fouten in een financieringsopzet?',antwoord:`Vergeten posten, dubbele posten en verkeerde eigen inbreng komen veel voor. Ook een onjuiste verdeling van fiscaal aftrekbare en niet-aftrekbare kosten. Laat de opzet sluiten op de nota van afrekening. Controleer altijd de totalen.`,tags:['financieringsopzet','fouten','controle'],bron:''},
 {id:'psx-112',thema:'praktijk-software',vraag:'Hoe verdeel ik de financieringsbehoefte over box 1 en box 3?',antwoord:`Kosten voor aankoop, verbetering of onderhoud van de eigen woning kunnen in box 1. Andere bestedingen, zoals roerende zaken, passen daar niet. Leg de verdeling vast per post. Bij twijfel overleg je met een fiscalist.`,tags:['box1','box3','financieringsopzet'],bron:'Wet IB 2001'},
 {id:'psx-113',thema:'praktijk-software',vraag:'Welke kosten zijn fiscaal aftrekbaar bij financiering van de eigen woning?',antwoord:`Kosten die rechtstreeks verband houden met het afsluiten van de eigenwoningschuld zijn vaak aftrekbaar. Denk aan advies- en bemiddelingskosten, taxatie en notariskosten voor de hypotheekakte. Overdrachtsbelasting is niet aftrekbaar. Controleer de actuele regels bij de Belastingdienst.`,tags:['aftrekbaar','financieringskosten','fiscaal'],bron:'Belastingdienst'},
 {id:'psx-114',thema:'praktijk-software',vraag:'Hoe ga ik om met een eigen inbreng die later beschikbaar komt?',antwoord:`Plan of het geld vóór passeren beschikbaar is. Is dat niet zo, dan is overbrugging of een andere opzet nodig. Leg de afspraken en bewijsstukken vast. Bespreek het risico van vertraging met de klant.`,tags:['eigen-inbreng','beschikbaarheid','passeren'],bron:''},
 {id:'psx-115',thema:'praktijk-software',vraag:'Waarom moet de financieringsopzet aansluiten op de offerte?',antwoord:`De notaris werkt met de bedragen uit de offerte en de nota van afrekening. Verschillen leiden tot tekorten of vragen bij passeren. Controleer leningbedragen, depots en eigen inbreng. Leg de laatste versie vast.`,tags:['financieringsopzet','offerte','notaris'],bron:''},
 {id:'psx-116',thema:'praktijk-software',vraag:'Hoe verwerk ik een bouwdepot in de financieringsopzet?',antwoord:`Neem het bouwdepot op als aparte post die aansluit op de verbouwingsspecificatie. Het depot wordt uit de lening gevormd. Noteer de looptijd en de declaratievoorwaarden. Controleer de voorwaarden van de geldverstrekker.`,tags:['bouwdepot','financieringsopzet','verbouwing'],bron:''},
 {id:'psx-117',thema:'praktijk-software',vraag:'Hoe ga ik om met een energiebespaarbudget of verduurzamingsdepot?',antwoord:`Neem het op als aparte post met de geplande maatregelen. Controleer of de maatregelen passen binnen de regels van de geldverstrekker. Leg de looptijd van het depot vast. Bewaak de declaraties met de klant.`,tags:['verduurzamingsdepot','energiebesparing','financieringsopzet'],bron:''},
 {id:'psx-118',thema:'praktijk-software',vraag:'Wat leg ik vast als de klant meer eigen geld inbrengt dan nodig?',antwoord:`Noteer de reden en bespreek de gevolgen voor buffer en liquiditeit. Een lagere lening kan gunstig zijn, maar weinig reserve brengt risico. Leg de afweging vast. Laat de klant bewust kiezen.`,tags:['eigen-inbreng','buffer','afweging'],bron:''},
 {id:'psx-119',thema:'praktijk-software',vraag:'Hoe ga ik om met een rekenvoorbeeld van kosten koper zonder actuele tarieven?',antwoord:`Gebruik in je voorbeeld de posten, niet vaste percentages. Denk aan overdrachtsbelasting, notaris, taxatie, advies en bankgarantie. Vul de bedragen in op basis van actuele offertes en tarieven. Verwijs voor tarieven naar de Belastingdienst.`,tags:['kosten-koper','rekenvoorbeeld','tarieven'],bron:'Belastingdienst'},
 {id:'psx-120',thema:'praktijk-software',vraag:'Hoe verwerk ik een vrijstelling van overdrachtsbelasting in de opzet?',antwoord:`Controleer of de klant aan de voorwaarden voldoet en leg het bewijs vast. Denk aan leeftijd, eerste keer gebruik en woningwaardegrens. Gebruik de actuele voorwaarden van de Belastingdienst. De notaris toetst dit ook.`,tags:['overdrachtsbelasting','vrijstelling','startersvrijstelling'],bron:'Belastingdienst'},
 {id:'psx-121',thema:'praktijk-software',vraag:'Hoe ga ik om met kosten die de verkoper betaalt?',antwoord:`Noteer welke kosten de verkoper draagt volgens de koopovereenkomst. Neem ze niet op als kosten voor de koper. Controleer of de nota van afrekening dit volgt. Leg afwijkingen vast.`,tags:['verkoper','kosten','koopovereenkomst'],bron:''},
 {id:'psx-122',thema:'praktijk-software',vraag:'Wat doe ik als de klant de woning koopt kosten koper met vrij op naam?',antwoord:`Kosten koper betekent dat de koper overdrachtskosten betaalt. Vrij op naam komt vooral bij nieuwbouw voor en betekent dat die kosten in de prijs zitten. Lees de koopovereenkomst goed. Pas de opzet hierop aan.`,tags:['kosten-koper','vrij-op-naam','nieuwbouw'],bron:''},
 {id:'psx-123',thema:'praktijk-software',vraag:'Hoe ga ik om met bouwrente bij nieuwbouw?',antwoord:`Bouwrente is de rente over termijnen die de koper betaalt over de grond of eerdere termijnen. Neem dit op in de opzet als het in de overeenkomst staat. Bespreek de dubbele lasten tijdens de bouw. Controleer de fiscale behandeling bij de Belastingdienst.`,tags:['bouwrente','nieuwbouw','financieringsopzet'],bron:'Belastingdienst'},
 {id:'psx-124',thema:'praktijk-software',vraag:'Hoe verwerk ik meerwerk bij nieuwbouw in de financiering?',antwoord:`Neem meerwerk op dat vóór of bij passeren bekend is. Laat meerwerk onderbouwen met de opdracht of offerte. Controleer of het in het bouwdepot past. Controleer de voorwaarden van de geldverstrekker.`,tags:['meerwerk','nieuwbouw','bouwdepot'],bron:''},
 {id:'psx-125',thema:'praktijk-software',vraag:'Hoe bereken ik de maximale lening zonder jaarafhankelijke cijfers te noemen?',antwoord:`Bepaal het toetsinkomen en het financieringslastpercentage uit de actuele tabel. Bereken daarmee de maximale maandlast en vertaal die naar een lening met de toetsrente. Tel energielabelruimte apart op. Gebruik de actuele normen van Nibud en de geldverstrekker.`,tags:['maximale-lening','leennormen','berekening'],bron:'Nibud'},
 {id:'psx-126',thema:'praktijk-software',vraag:'Waarom tellen beide inkomens volledig mee bij een tweeverdiener?',antwoord:`Volgens de leennormen telt het tweede inkomen volledig mee. Daardoor kan een stel meer lenen dan voorheen. Het risico bij verlies van één inkomen blijft wel bestaan. Bespreek dit en leg de afweging vast.`,tags:['tweeverdieners','leennormen','risico'],bron:'Nibud'},
 {id:'psx-127',thema:'praktijk-software',vraag:'Wat is de toeslag voor alleenstaanden in de leennormen?',antwoord:`Voor alleenstaanden telt een vast bedrag van €17.000 extra mee bij het toetsinkomen. Dat compenseert hogere vaste lasten van één inkomen. Gebruik het bedrag uit de actuele normen. Controleer hoe de geldverstrekker het toepast.`,tags:['alleenstaanden','leennormen','toetsinkomen'],bron:'Nibud'},
 {id:'psx-128',thema:'praktijk-software',vraag:'Hoe ga ik om met een opzet bij een oversluiting?',antwoord:`Neem de aflossing van de oude lening, boeterente en kosten op. Bepaal welk deel fiscaal eigenwoningschuld blijft. Leg de rentevergelijking en terugverdientijd vast. Bespreek of oversluiten in het belang van de klant is.`,tags:['oversluiten','boeterente','financieringsopzet'],bron:''},
 {id:'psx-129',thema:'praktijk-software',vraag:'Wat leg ik vast bij een verhoging van de hypotheek?',antwoord:`Noteer het doel van de verhoging en de fiscale behandeling. Controleer of de nieuwe lening aan de aflossingseis voldoet. Leg de nieuwe totale lasten en de toets vast. Bespreek de gevolgen voor de risicos.`,tags:['verhoging','fiscaal','toetsing'],bron:'Wet IB 2001'},
 {id:'psx-130',thema:'praktijk-software',vraag:'Hoe ga ik om met de aflossingseis bij een nieuwe eigenwoningschuld?',antwoord:`Voor renteaftrek moet nieuwe eigenwoningschuld vanaf 2013 in maximaal 360 maanden minstens annuïtair worden afgelost. Lineair aflossen voldoet ook. Overgangsrecht kan gelden voor schulden van vóór 2013. Leg vast welk regime per leningdeel geldt.`,tags:['aflossingseis','360-maanden','fiscaal'],bron:'Wet IB 2001'},
 {id:'psx-131',thema:'praktijk-software',vraag:'Hoe documenteer ik leningdelen met verschillend fiscaal regime?',antwoord:`Geef per leningdeel aan of het onder overgangsrecht, nieuw regime of box 3 valt. Noteer de resterende looptijd van de renteaftrek. Bewaar de onderbouwing. Dit voorkomt fouten bij latere wijzigingen.`,tags:['leningdelen','fiscaal-regime','vastlegging'],bron:''},
 {id:'psx-132',thema:'praktijk-software',vraag:'Wat doe ik als de financieringsopzet een tekort laat zien?',antwoord:`Zoek de oorzaak en bespreek opties, zoals extra eigen geld of een lagere koopsom. Een tekort mag niet ongemerkt naar de notaris gaan. Leg de oplossing en klantkeuze vast. Controleer of de opzet daarna sluit.`,tags:['tekort','financieringsopzet','oplossing'],bron:''},
 {id:'psx-133',thema:'praktijk-software',vraag:'Hoe ga ik om met een overwaarde-financiering bij doorstroming?',antwoord:`Bereken de verwachte overwaarde na aftrek van hypotheek en verkoopkosten. Houd rekening met een EWR. Neem bij nog niet verkochte woning een realistische verkoopwaarde. Leg de aannames vast.`,tags:['overwaarde','doorstromer','ewr'],bron:''},
 {id:'psx-134',thema:'praktijk-software',vraag:'Hoe bereken ik de terugverdientijd van oversluiten?',antwoord:`Zet de eenmalige kosten, zoals boeterente en advieskosten, af tegen de maandelijkse besparing. Kijk naar netto bedragen na fiscaal effect. Neem de looptijd van de nieuwe rentevaste periode mee. Leg de berekening vast.`,tags:['oversluiten','terugverdientijd','rekenvoorbeeld'],bron:''},
 {id:'psx-135',thema:'praktijk-software',vraag:'Hoe ga ik om met een doorlopend krediet dat de klant gaat aflossen?',antwoord:`Neem het alleen niet mee in de toets als de aflossing en opheffing vaststaan. Geldverstrekkers vragen vaak bewijs van opheffing. Leg de afspraak vast. Controleer de voorwaarden van de geldverstrekker.`,tags:['krediet','aflossen','toetsing'],bron:''},
 {id:'psx-136',thema:'praktijk-software',vraag:'Hoe registreer ik een tweede woning in de financieringsopzet?',antwoord:`Een tweede woning valt in box 3 en is geen eigen woning. Financiering valt dus niet onder de eigenwoningregeling. Niet elke geldverstrekker financiert dit. Controleer de voorwaarden en leg de fiscale behandeling vast.`,tags:['tweede-woning','box3','financiering'],bron:'Belastingdienst'},
 {id:'psx-137',thema:'praktijk-software',vraag:'Wat leg ik vast als de klant een deel aflossingsvrij wil houden?',antwoord:`Controleer of dat deel onder overgangsrecht valt of in box 3 komt. Bespreek de gevolgen voor restschuld en latere lasten. Leg de afweging en klantkeuze vast. Controleer de voorwaarden van de geldverstrekker.`,tags:['aflossingsvrij','overgangsrecht','afweging'],bron:''},
 {id:'psx-138',thema:'praktijk-software',vraag:'Hoe ga ik om met een opzet waarin de oude woning nog niet verkocht is?',antwoord:`De oude woning blijft tot drie jaar fiscaal eigen woning als die leeg staat en te koop is. Bereken dubbele lasten en eventuele overbrugging. Leg het scenario vast waarin verkoop langer duurt. Bespreek de buffer met de klant.`,tags:['dubbele-lasten','verkoop','fiscaal'],bron:'Wet IB 2001'},
 {id:'psx-139',thema:'praktijk-software',vraag:'Wat gebeurt er met de opzet als de verkoopprijs van de oude woning lager is?',antwoord:`Een lagere verkoopprijs verlaagt de overwaarde en mogelijk de eigen inbreng. Bereken vooraf een scenario met een lagere prijs. Leg vast wat de klant doet bij een tekort. Bespreek of een restschuld kan ontstaan.`,tags:['verkoopprijs','overwaarde','scenario'],bron:''},
 {id:'psx-140',thema:'praktijk-software',vraag:'Hoe ga ik om met afrondingen in financieringslastpercentages?',antwoord:`De financieringslastpercentages in de leennormen zijn afgerond op 0,1 procent. Gebruik de tabel van de actuele normen en niet een eigen afronding. Kleine afwijkingen in de software kunnen hierdoor ontstaan. Leg vast welke tabel is gebruikt.`,tags:['financieringslast','afronding','leennormen'],bron:'Nibud'},
 {id:'psx-141',thema:'praktijk-software',vraag:'Waarom controleer ik de toetsrente in de berekening?',antwoord:`De toetsrente bepaalt de maximale lening bij korte rentevaste periodes. Een verkeerde instelling leidt tot een te hoge of te lage uitkomst. Gebruik de actuele toetsrente van de AFM. Controleer de instelling in de software.`,tags:['toetsrente','afm','software'],bron:'AFM'},
 {id:'psx-142',thema:'praktijk-software',vraag:'Hoe ga ik om met de Wet Hillen in de lastenberekening?',antwoord:`Vanaf 2019 wordt de Wet Hillen in 30 jaar afgebouwd. Klanten met weinig of geen eigenwoningschuld merken dit in hun belasting. Neem het effect mee in je netto berekening. Gebruik de actuele percentages van de Belastingdienst.`,tags:['wet-hillen','eigenwoningforfait','netto-lasten'],bron:'Belastingdienst'},
 {id:'psx-143',thema:'praktijk-software',vraag:'Hoe presenteer ik bruto en netto lasten aan de klant?',antwoord:`Toon beide en leg het verschil uit. Netto lasten hangen af van renteaftrek, eigenwoningforfait en persoonlijke situatie. Wijs erop dat de aftrek in de tijd verandert. Leg vast welke uitgangspunten je gebruikte.`,tags:['bruto-netto','lasten','uitleg'],bron:''},
 {id:'psx-144',thema:'praktijk-software',vraag:'Wat doe ik als de software een andere maximale lening geeft dan de geldverstrekker?',antwoord:`Controleer de invoer, normen en productvoorwaarden in de software. Geldverstrekkers kunnen eigen normen of uitzonderingen hanteren. De geldverstrekker beslist uiteindelijk. Leg vast welke uitkomst je hebt gebruikt en waarom.`,tags:['maximale-lening','software','verschil'],bron:''},
 {id:'psx-145',thema:'praktijk-software',vraag:'Hoe ga ik om met de energielabel-leenruimte als het label na verduurzaming verandert?',antwoord:`Bij aankoop telt het label op het moment van aanvraag. De verduurzamingsruimte hangt af van het huidige label en de maatregelen. Geldverstrekkers kunnen een maatwerkadvies of offertes vragen. Controleer de voorwaarden van de geldverstrekker.`,tags:['energielabel','verduurzaming','leenruimte'],bron:'Nibud'},
 {id:'psx-146',thema:'praktijk-software',vraag:'Hoe ga ik om met een starterslening in de opzet?',antwoord:`Neem de starterslening als aparte lening op met de eigen voorwaarden. Controleer of de gemeente of regeling deze aanbiedt. De toets en volgorde van aanvragen kunnen afwijken. Controleer de voorwaarden van de verstrekker.`,tags:['starterslening','gemeente','financieringsopzet'],bron:''},
 {id:'psx-147',thema:'praktijk-software',vraag:'Hoe controleer ik of de leningdelen in de opzet optellen tot het totaal?',antwoord:`Tel alle leningdelen op en vergelijk met de financieringsbehoefte minus eigen inbreng. Een klein verschil kan op afronding wijzen, een groot verschil op een fout. Corrigeer vóór verzending. Leg de eindcontrole vast.`,tags:['leningdelen','controle','totalen'],bron:''},
 {id:'psx-148',thema:'praktijk-software',vraag:'Hoe verwerk ik een NHG-aanvraag in de opzet zonder vaste grens te noemen?',antwoord:`Controleer of de lening binnen de actuele kostengrens valt. Neem de borgtochtprovisie op als kostenpost. Controleer welke kosten meetellen voor de grens. Verwijs voor de actuele grens naar NHG.`,tags:['nhg','kostengrens','financieringsopzet'],bron:'NHG'},
 {id:'psx-149',thema:'praktijk-software',vraag:'Wat doe ik als de klant twee leningdelen met verschillende rentevaste periodes wil?',antwoord:`Leg per leningdeel de rentevaste periode en reden vast. Bespreek het renterisico van elk deel. Let op de toetsrente bij korte periodes. Controleer of de geldverstrekker dit toestaat.`,tags:['rentevaste-periode','leningdelen','renterisico'],bron:''},
 {id:'psx-150',thema:'praktijk-software',vraag:'Hoe leg ik vast welke versie van de financieringsopzet definitief is?',antwoord:`Geef elke versie een datum of versienummer. Markeer de versie die aansluit op offerte en nota van afrekening als definitief. Bewaar eerdere versies apart. Zo is later te zien op welke cijfers het advies rustte.`,tags:['versiebeheer','financieringsopzet','vastlegging'],bron:''},
 {id:'psx-151',thema:'praktijk-software',vraag:'Welke stukken stuur ik naar de notaris en wanneer?',antwoord:`De geldverstrekker stuurt meestal de hypotheekopdracht naar de notaris. Jij levert vaak de financieringsopzet en contactgegevens. Doe dit ruim vóór de passeerdatum. Controleer welke stukken de notaris nog mist.`,tags:['notaris','stukken','passeren'],bron:''},
 {id:'psx-152',thema:'praktijk-software',vraag:'Wat doe ik als de notaris de hypotheekopdracht nog niet heeft?',antwoord:`Vraag bij de geldverstrekker na of de opdracht is verstuurd. Controleer of alle voorwaarden uit de offerte zijn vervuld. Openstaande stukken blokkeren vaak de opdracht. Informeer de klant over het risico op uitstel.`,tags:['notaris','hypotheekopdracht','voorwaarden'],bron:''},
 {id:'psx-153',thema:'praktijk-software',vraag:'Wat is een tekort op de nota van afrekening en hoe ontstaat het?',antwoord:`Een tekort betekent dat de klant bij passeren moet bijbetalen. Oorzaken zijn vergeten kosten, een lager leningbedrag of een andere verrekening. Vergelijk de nota met de financieringsopzet. Los het verschil vóór passeren op.`,tags:['nota-van-afrekening','tekort','controle'],bron:''},
 {id:'psx-154',thema:'praktijk-software',vraag:'Hoe ga ik om met een passeerdatum die verschuift?',antwoord:`Controleer of de offerte en de rentezekerheid nog geldig zijn. Kijk of de ontbindingsdatum en bankgarantie meebewegen. Informeer alle partijen tijdig. Leg de nieuwe datum en afspraken vast.`,tags:['passeerdatum','termijnen','offerte'],bron:''},
 {id:'psx-155',thema:'praktijk-software',vraag:'Wat gebeurt er als de offerte verloopt vóór passeren?',antwoord:`Dan is vaak een verlenging of nieuwe offerte nodig. Verlenging kan kosten of een andere rente met zich meebrengen. Controleer de voorwaarden van de geldverstrekker. Bewaak de einddatum vanaf het moment van uitbrengen.`,tags:['offerte','geldigheid','verlenging'],bron:''},
 {id:'psx-156',thema:'praktijk-software',vraag:'Hoe bewaak ik de termijnen van alle partijen in één dossier?',antwoord:`Leg alle data vast in een planning: ontbinding, bankgarantie, offerte, taxatie en passeren. Gebruik signaleringen in je software. Wijs per dossier een verantwoordelijke aan. Controleer de planning bij elke statuswijziging.`,tags:['termijnen','planning','signalering'],bron:''},
 {id:'psx-157',thema:'praktijk-software',vraag:'Wat doe ik als de ontbindingsdatum dreigt te verlopen?',antwoord:`Overleg tijdig met de klant en de makelaar over uitstel. Uitstel moet schriftelijk met de verkoper worden afgesproken. Zonder uitstel kan de klant zich niet meer op de voorwaarde beroepen. Leg alle afspraken vast.`,tags:['ontbindende-voorwaarde','uitstel','termijnen'],bron:''},
 {id:'psx-158',thema:'praktijk-software',vraag:'Wat leg ik vast als de klant de ontbindingsdatum laat verlopen zonder financiering?',antwoord:`Noteer dat je de klant hebt gewaarschuwd en wanneer. Leg de status van de aanvraag op dat moment vast. Bespreek de mogelijke gevolgen van de koopovereenkomst. Adviseer juridisch advies bij geschillen.`,tags:['ontbindende-voorwaarde','risico','vastlegging'],bron:''},
 {id:'psx-159',thema:'praktijk-software',vraag:'Wanneer vraag ik een bankgarantie aan?',antwoord:`Vaak moet de bankgarantie binnen een in de koopovereenkomst afgesproken termijn bij de notaris zijn. Vraag haar tijdig aan zodat die termijn wordt gehaald. Controleer bedrag en datum in de overeenkomst. Leg de aanvraag en levering vast.`,tags:['bankgarantie','termijnen','koopovereenkomst'],bron:''},
 {id:'psx-160',thema:'praktijk-software',vraag:'Wat is het verschil tussen een bankgarantie en een waarborgsom?',antwoord:`Bij een waarborgsom stort de koper geld bij de notaris. Een bankgarantie is een garantie van een bank of verzekeraar dat het bedrag wordt betaald. Een bankgarantie kost een vergoeding maar vraagt geen eigen geld. Leg de gekozen vorm vast.`,tags:['bankgarantie','waarborgsom','notaris'],bron:''},
 {id:'psx-161',thema:'praktijk-software',vraag:'Waar let ik op bij de koopovereenkomst als adviseur?',antwoord:`Kijk naar koopsom, roerende zaken, ontbindende voorwaarden, data en waarborg. Let op bijzondere bepalingen zoals erfpacht of anti-speculatiebeding. Signaleer afwijkingen naar de klant. Leg je controle vast.`,tags:['koopovereenkomst','controle','bepalingen'],bron:''},
 {id:'psx-162',thema:'praktijk-software',vraag:'Wat doe ik als de koopovereenkomst een ander bedrag noemt dan de financieringsopzet?',antwoord:`Gebruik de koopovereenkomst als uitgangspunt. Pas de opzet en zo nodig de aanvraag aan. Ga na of er een aanvulling of addendum is. Bespreek de gevolgen met de klant.`,tags:['koopovereenkomst','koopsom','financieringsopzet'],bron:''},
 {id:'psx-163',thema:'praktijk-software',vraag:'Hoe ga ik om met een opzegging van de oude hypotheek bij doorstroming?',antwoord:`De notaris lost de oude hypotheek af bij verkoop van de woning. Vraag tijdig een aflossingsnota op. Let op boeterente en afspraken over meenemen. Controleer of de nota op tijd bij de notaris is.`,tags:['aflossingsnota','oude-hypotheek','notaris'],bron:''},
 {id:'psx-164',thema:'praktijk-software',vraag:'Wat controleer ik op de hypotheekakte?',antwoord:`Controleer namen, bedragen, leningdelen en het onderpand. Kijk of de inschrijving overeenkomt met de offerte. Vragen over de juridische tekst leg je bij de notaris neer. Leg vast dat je de concepten hebt bekeken.`,tags:['hypotheekakte','notaris','controle'],bron:''},
 {id:'psx-165',thema:'praktijk-software',vraag:'Hoe informeer ik de klant over de passeerafspraak?',antwoord:`Vertel wat er gebeurt bij het passeren en welke stukken en ID nodig zijn. Wijs op het tijdig overmaken van eventueel eigen geld. Geef aan bij wie de klant terecht kan met vragen. Leg vast dat je dit hebt gecommuniceerd.`,tags:['passeren','klantinformatie','notaris'],bron:''},
 {id:'psx-166',thema:'praktijk-software',vraag:'Wanneer moet eigen geld op de rekening van de notaris staan?',antwoord:`De notaris geeft aan wanneer het geld binnen moet zijn. Dat is meestal enkele dagen vóór passeren. Te laat storten kan het passeren vertragen. Controleer de instructies van de notaris.`,tags:['eigen-geld','notaris','termijnen'],bron:''},
 {id:'psx-167',thema:'praktijk-software',vraag:'Wat doe ik na het passeren van de akte?',antwoord:`Controleer of de eerste maandlast en eventueel bouwdepot correct zijn verwerkt. Archiveer de definitieve stukken. Plan het eerste nazorgmoment. Leg de afronding van het traject vast.`,tags:['passeren','afronding','nazorg'],bron:''},
 {id:'psx-168',thema:'praktijk-software',vraag:'Hoe ga ik om met verzekeringen die bij passeren moeten ingaan?',antwoord:`Controleer of overlijdensrisico- en opstalverzekering tijdig zijn geregeld. Geldverstrekkers kunnen dit als voorwaarde stellen. Leg ingangsdata en polisnummers vast. Controleer de voorwaarden van de geldverstrekker en verzekeraar.`,tags:['verzekeringen','passeren','voorwaarden'],bron:''},
 {id:'psx-169',thema:'praktijk-software',vraag:'Wat is een gezondheidsverklaring en waarom kan die het traject vertragen?',antwoord:`Voor een overlijdensrisicoverzekering vraagt de verzekeraar vaak naar de gezondheid. Een medische beoordeling kan tijd kosten. Begin hier vroeg mee. Leg de status vast en bewaak de termijn.`,tags:['gezondheidsverklaring','orv','termijnen'],bron:''},
 {id:'psx-170',thema:'praktijk-software',vraag:'Wat leg ik vast als de klant geen overlijdensrisicoverzekering wil?',antwoord:`Noteer dat je het risico hebt besproken en welke bedragen speelden. Leg de keuze en reden van de klant vast. Controleer of de geldverstrekker het als voorwaarde stelt. Laat de keuze bevestigen.`,tags:['orv','afwijkende-keuze','vastlegging'],bron:''},
 {id:'psx-171',thema:'praktijk-software',vraag:'Hoe plan ik nazorg na het afsluiten van de hypotheek?',antwoord:`Leg vaste momenten vast, zoals einde rentevaste periode en grote levensgebeurtenissen. Gebruik signaleringen in je software. Spreek met de klant af hoe vaak je contact hebt. Leg de nazorgafspraak schriftelijk vast.`,tags:['nazorg','planning','signalering'],bron:''},
 {id:'psx-172',thema:'praktijk-software',vraag:'Wat bespreek ik bij een periodieke hypotheekcheck?',antwoord:`Bespreek veranderingen in inkomen, gezin, woning en wensen. Kijk naar rente, aflossing, verzekeringen en risicos. Beoordeel of aanpassing nodig is. Leg de uitkomst vast.`,tags:['hypotheekcheck','nazorg','evaluatie'],bron:''},
 {id:'psx-173',thema:'praktijk-software',vraag:'Hoe ga ik om met een klant die geen nazorg wil?',antwoord:`Leg vast dat de klant geen periodieke nazorg wenst. Informeer hem over momenten waarop actie nodig kan zijn. Bewaar deze communicatie in het dossier. Controleer of je doorlopende vergoeding hierop aansluit.`,tags:['nazorg','weigering','vastlegging'],bron:''},
 {id:'psx-174',thema:'praktijk-software',vraag:'Wanneer neem ik contact op rond het einde van de rentevaste periode?',antwoord:`Begin ruim voor de einddatum, zodat de klant opties kan vergelijken. Geldverstrekkers sturen vaak zelf een aanbod. Leg je contactmoment vast. Bespreek ook of de lening nog bij de situatie past.`,tags:['rentevaste-periode','nazorg','renteverlenging'],bron:''},
 {id:'psx-175',thema:'praktijk-software',vraag:'Hoe ga ik om met een klant met betalingsproblemen?',antwoord:`Moedig de klant aan zo vroeg mogelijk contact op te nemen met de geldverstrekker. Inventariseer de oorzaak en de mogelijkheden. Verwijs zo nodig naar schuldhulpverlening. Leg je contact en verwijzingen vast.`,tags:['betalingsproblemen','nazorg','schuldhulp'],bron:''},
 {id:'psx-176',thema:'praktijk-software',vraag:'Wat doe ik bij een scheiding van een bestaande klant?',antwoord:`Inventariseer de wensen van beide partijen apart. Let op belangenverstrengeling als je beide partijen adviseert. Kijk naar overname van de lening en ontslag uit hoofdelijkheid. Leg vast wie je adviseert en waarover.`,tags:['scheiding','nazorg','belangenconflict'],bron:''},
 {id:'psx-177',thema:'praktijk-software',vraag:'Hoe ga ik om met het overlijden van een klant?',antwoord:`Toon begrip en ga zorgvuldig om met de nabestaanden. Inventariseer de verzekeringen en uitkeringen. Help bij het melden aan geldverstrekker en verzekeraar. Leg vast wie je namens wie informeert.`,tags:['overlijden','nabestaanden','nazorg'],bron:''},
 {id:'psx-178',thema:'praktijk-software',vraag:'Wat doe ik als een klant extra wil aflossen?',antwoord:`Bekijk de boetevrije ruimte bij de geldverstrekker. Bespreek de gevolgen voor fiscus, liquiditeit en buffer. Overweeg welk leningdeel het eerst wordt afgelost. Leg de afweging vast.`,tags:['extra-aflossen','boetevrij','nazorg'],bron:''},
 {id:'psx-179',thema:'praktijk-software',vraag:'Hoe ga ik om met een renteherziening via rentemiddeling bij een bestaande klant?',antwoord:`Vergelijk de gemiddelde rente met alternatieven, zoals oversluiten of wachten. Kijk naar kosten en looptijd. Laat de klant de berekening zien. Leg de afweging vast.`,tags:['rentemiddeling','nazorg','vergelijking'],bron:''},
 {id:'psx-180',thema:'praktijk-software',vraag:'Wat leg ik vast bij een verhuizing van de hypotheek naar een nieuwe woning?',antwoord:`Noteer welke leningdelen worden meegenomen en tegen welke voorwaarden. Leg de nieuwe financieringsopzet en toets vast. Controleer de termijn van de meeneemregeling. Bespreek eventuele aanvullende financiering.`,tags:['meeneemregeling','verhuizing','vastlegging'],bron:''},
 {id:'psx-181',thema:'praktijk-software',vraag:'Hoe ga ik om met een renteaanpassing bij verbetering van de risicoklasse?',antwoord:`Bij aflossing of waardestijging kan een lagere risicoklasse gelden. Sommige geldverstrekkers passen dit automatisch aan, anderen op verzoek. Vraag zo nodig een nieuwe taxatie. Controleer de voorwaarden van de geldverstrekker.`,tags:['risicoklasse','renteaanpassing','nazorg'],bron:''},
 {id:'psx-182',thema:'praktijk-software',vraag:'Welke signalen in nazorg wijzen op een groter risico voor de klant?',antwoord:`Denk aan baanverlies, ziekte, scheiding, achterstand of een aflossingsvrije lening die afloopt. Ook pensionering is een aandachtspunt. Neem dan actief contact op. Leg je signalering en actie vast.`,tags:['risicosignalen','nazorg','klantcontact'],bron:'AFM'},
 {id:'psx-183',thema:'praktijk-software',vraag:'Hoe ga ik om met een aflossingsvrij leningdeel dat binnenkort afloopt?',antwoord:`Bespreek ruim voor de einddatum hoe de klant gaat aflossen of herfinancieren. Bekijk of herfinanciering onder de huidige normen haalbaar is. Inventariseer de opties. Leg de afspraken vast.`,tags:['aflossingsvrij','einddatum','herfinanciering'],bron:'AFM'},
 {id:'psx-184',thema:'praktijk-software',vraag:'Wanneer controleer ik de overlijdensrisicoverzekering opnieuw?',antwoord:`Doe dat bij een wijziging in hypotheek, gezinssituatie of inkomen. Kijk of het verzekerde bedrag nog past. Een overbodige of te lage dekking is een signaal. Leg de check vast.`,tags:['orv','evaluatie','nazorg'],bron:''},
 {id:'psx-185',thema:'praktijk-software',vraag:'Hoe ga ik om met een klant die tussentijds van adviseur wil wisselen?',antwoord:`Respecteer de keuze en help bij een ordelijke overdracht. Maak afspraken over doorlopende vergoedingen en stukken. Let op de AVG bij overdracht. Leg de beëindiging vast.`,tags:['adviseurswissel','overdracht','avg'],bron:''},
 {id:'psx-186',thema:'praktijk-software',vraag:'Hoe ga ik om met de opstalverzekering bij een appartement?',antwoord:`Bij een appartement regelt de VvE vaak de opstalverzekering. Controleer dit in de stukken. De klant heeft wel een eigen inboedelverzekering nodig. Leg vast wat je hebt gecontroleerd.`,tags:['opstal','vve','appartement'],bron:''},
 {id:'psx-187',thema:'praktijk-software',vraag:'Wat doe ik als een bouwdepot bijna verloopt?',antwoord:`Controleer de resterende looptijd en het bedrag in depot. Help de klant met tijdige declaraties. Vraag zo nodig verlenging aan als de geldverstrekker dat toestaat. Leg vast wat met het restant gebeurt.`,tags:['bouwdepot','looptijd','nazorg'],bron:''},
 {id:'psx-188',thema:'praktijk-software',vraag:'Hoe bewaak ik de declaraties uit een bouwdepot?',antwoord:`Spreek met de klant af welke facturen worden ingediend. Controleer of de facturen passen bij de specificatie. Houd een overzicht van ingediende en uitbetaalde bedragen bij. Leg dit vast in het dossier.`,tags:['bouwdepot','declaraties','controle'],bron:''},
 {id:'psx-189',thema:'praktijk-software',vraag:'Wat leg ik vast als een klant zijn hypotheek bij een andere adviseur oversluit?',antwoord:`Noteer dat de klant elders heeft overgesloten. Beëindig je nazorgafspraak en eventuele doorlopende vergoeding. Archiveer het dossier volgens je bewaarbeleid. Leg de datum van beëindiging vast.`,tags:['oversluiten','beëindiging','dossier'],bron:''},
 {id:'psx-190',thema:'praktijk-software',vraag:'Hoe stem ik met de makelaar af over de voortgang van de financiering?',antwoord:`Deel alleen informatie waarvoor de klant toestemming heeft gegeven. Geef de status van de financiering, niet de details van inkomen of verplichtingen. Leg de toestemming vast. Zo blijf je binnen de AVG.`,tags:['makelaar','privacy','voortgang'],bron:'AVG'},
 {id:'psx-191',thema:'praktijk-software',vraag:'Hoe ga ik om met een korte levertijd bij een snelle aankoop?',antwoord:`Plan direct taxatie, aanvraag en stukken. Check vooraf of de geldverstrekker binnen de termijn kan leveren. Wees eerlijk over risicos van een korte ontbindingstermijn. Leg je inschatting vast.`,tags:['termijnen','snelle-aankoop','planning'],bron:''},
 {id:'psx-192',thema:'praktijk-software',vraag:'Wat doe ik als de geldverstrekker meer tijd nodig heeft dan verwacht?',antwoord:`Informeer de klant en de makelaar tijdig. Vraag zo nodig uitstel van ontbinding of passeren aan. Leg de communicatie vast. Overweeg een alternatieve geldverstrekker als de termijn niet haalbaar is.`,tags:['vertraging','geldverstrekker','termijnen'],bron:''},
 {id:'psx-193',thema:'praktijk-software',vraag:'Hoe ga ik om met een voorwaarde in de offerte die niet kan worden vervuld?',antwoord:`Overleg met de geldverstrekker over een alternatief. Leg vast welke voorwaarde het probleem vormt en waarom. Informeer de klant over de gevolgen. Controleer of de ontbindingsdatum nog haalbaar is.`,tags:['offertevoorwaarden','geldverstrekker','oplossing'],bron:''},
 {id:'psx-194',thema:'praktijk-software',vraag:'Hoe controleer ik dat alle opschortende voorwaarden zijn afgevinkt vóór passeren?',antwoord:`Maak een lijst van de voorwaarden uit offerte en koopovereenkomst. Vink per voorwaarde af wanneer bewijs is geleverd. Vraag de geldverstrekker om bevestiging. Leg de eindcontrole vast.`,tags:['opschortende-voorwaarden','checklist','passeren'],bron:''},
 {id:'psx-195',thema:'praktijk-software',vraag:'Wat is de rol van de adviseur bij de sleuteloverdracht?',antwoord:`De adviseur heeft daar geen formele rol. Je kunt wel de klant voorbereiden op de laatste inspectie en het passeren. Wijs op het controleren van meterstanden en de staat van de woning. Bied hulp bij vragen.`,tags:['sleuteloverdracht','passeren','klantbegeleiding'],bron:''},
 {id:'psx-196',thema:'praktijk-software',vraag:'Hoe ga ik om met een bijlening na een paar jaar?',antwoord:`Behandel de bijlening als nieuw advies met actuele inventarisatie en toets. Leg het doel en de fiscale behandeling vast. Controleer of aflossingseis en overgangsrecht goed zijn toegepast. Leg de afweging vast.`,tags:['bijlening','advies','fiscaal'],bron:'Wet IB 2001'},
 {id:'psx-197',thema:'praktijk-software',vraag:'Hoe informeer ik de klant over het vervallen van de EWR?',antwoord:`De eigenwoningreserve vervalt na 3 jaar. Leg vast wanneer de reserve is ontstaan en wanneer die vervalt. Informeer de klant als een nieuwe aankoop binnen die periode speelt. Verwijs bij twijfel naar een fiscalist.`,tags:['ewr','termijnen','fiscaal'],bron:'Wet IB 2001'},
 {id:'psx-198',thema:'praktijk-software',vraag:'Wanneer loopt de fiscale periode voor een leegstaande oude woning af?',antwoord:`Een leegstaande woning die te koop staat, blijft tot drie jaar fiscaal eigen woning. Bewaak die periode bij doorstromers. Na afloop valt de woning in box 3. Informeer de klant tijdig over de gevolgen.`,tags:['oude-woning','fiscaal','termijnen'],bron:'Wet IB 2001'},
 {id:'psx-199',thema:'praktijk-software',vraag:'Wat doe ik bij een klant die in de nazorg gaat verbouwen?',antwoord:`Inventariseer de plannen en de financieringsbehoefte. Kijk naar verhoging, bouwdepot of eigen geld. Bekijk ook de verduurzamingsruimte bij het actuele label. Leg advies en afweging vast.`,tags:['verbouwing','nazorg','financiering'],bron:''},
 {id:'psx-200',thema:'praktijk-software',vraag:'Hoe ga ik om met een verlengingsverzoek van de bankgarantie?',antwoord:`Bij uitstel van passeren moet de bankgarantie soms langer geldig zijn. Vraag de verlenging tijdig aan bij de uitgevende partij. Controleer de nieuwe einddatum. Leg de aanvraag en bevestiging vast.`,tags:['bankgarantie','verlenging','termijnen'],bron:''},
 {id:'psx-201',thema:'praktijk-software',vraag:'Hoe registreer ik een klacht intern?',antwoord:`Leg datum, klant, onderwerp, inhoud en behandelaar vast in een klachtenregister. Noteer ook de afhandeling en de uitkomst. Houd de termijnen uit je eigen klachtenprocedure aan. Gebruik het register om terugkerende oorzaken te zien.`,tags:['klachtenregister','registratie','klacht'],bron:''},
 {id:'psx-202',thema:'praktijk-software',vraag:'Wat is het verschil tussen een klacht en een vraag of uiting van ongenoegen?',antwoord:`Een klacht is een uiting van onvrede waarbij de klant een oplossing of erkenning verwacht. Twijfel je, behandel het dan als klacht. Leg in je procedure vast hoe je onderscheid maakt. Zo voorkom je dat klachten ongemerkt blijven liggen.`,tags:['klacht','definitie','procedure'],bron:''},
 {id:'psx-203',thema:'praktijk-software',vraag:'Wie behandelt bij voorkeur een klacht binnen het kantoor?',antwoord:`Bij voorkeur iemand die niet direct betrokken was bij het advies. In een eenmanszaak kan dat lastig zijn. Leg dan vast hoe je toch objectief beoordeelt. Een externe collega of klachtenfunctionaris kan helpen.`,tags:['klachtbehandeling','onafhankelijk','kantoor'],bron:''},
 {id:'psx-204',thema:'praktijk-software',vraag:'Wat leg ik vast in mijn eindreactie op een klacht?',antwoord:`Beschrijf de klacht, je onderzoek, je standpunt en eventuele oplossing. Verwijs naar de mogelijkheid van een klacht bij Kifid. Formuleer helder en zonder vakjargon. Bewaar de reactie in het dossier.`,tags:['eindreactie','kifid','klacht'],bron:'Kifid'},
 {id:'psx-205',thema:'praktijk-software',vraag:'Wanneer kan een klant naar Kifid?',antwoord:`Een klant kan bij Kifid terecht als de klacht na interne behandeling niet is opgelost. Kifid hanteert eigen termijnen en voorwaarden. Verwijs hiernaar in je eindreactie. Controleer de actuele voorwaarden bij Kifid.`,tags:['kifid','geschil','klacht'],bron:'Kifid'},
 {id:'psx-206',thema:'praktijk-software',vraag:'Hoe bereid ik me voor op een Kifid-procedure?',antwoord:`Verzamel het volledige dossier, inclusief inventarisatie, advies en communicatie. Een goed vastgelegd dossier is je belangrijkste bewijs. Meld de klacht zo nodig aan je beroepsaansprakelijkheidsverzekeraar. Volg de instructies van Kifid.`,tags:['kifid','dossier','bewijs'],bron:'Kifid'},
 {id:'psx-207',thema:'praktijk-software',vraag:'Moet ik een klacht melden aan mijn beroepsaansprakelijkheidsverzekeraar?',antwoord:`Veel polissen verplichten je om omstandigheden die tot een claim kunnen leiden tijdig te melden. Controleer de polisvoorwaarden. Te late melding kan dekking kosten. Leg de melding vast.`,tags:['bav','melding','klacht'],bron:''},
 {id:'psx-208',thema:'praktijk-software',vraag:'Hoe gebruik ik klachten om mijn werkwijze te verbeteren?',antwoord:`Analyseer periodiek de oorzaken van klachten. Kijk naar terugkerende patronen, zoals communicatie over termijnen of kosten. Pas procedures en checklists aan. Leg de verbeteracties vast.`,tags:['klachtanalyse','verbetering','kwaliteit'],bron:''},
 {id:'psx-209',thema:'praktijk-software',vraag:'Wat is een veelvoorkomende oorzaak van klachten over hypotheekadvies?',antwoord:`Onduidelijkheid over kosten, vertraging rond termijnen en onvoldoende uitleg over risicos komen vaak voor. Ook verwachtingen die niet zijn waargemaakt leiden tot onvrede. Duidelijke vastlegging en communicatie helpt. Bespreek risicos aantoonbaar.`,tags:['klachtoorzaak','communicatie','verwachtingen'],bron:''},
 {id:'psx-210',thema:'praktijk-software',vraag:'Hoe ga ik om met een klacht over een geldverstrekker?',antwoord:`Help de klant bij het indienen van de klacht bij de geldverstrekker. De geldverstrekker heeft een eigen klachtenprocedure. Leg vast welke rol jij hebt gespeeld. Bewaak dat je eigen advies niet ongemerkt ter discussie staat.`,tags:['klacht','geldverstrekker','ondersteuning'],bron:''},
 {id:'psx-211',thema:'praktijk-software',vraag:'Hoe richt ik een vier-ogenprincipe in een klein kantoor in?',antwoord:`Laat een collega of externe adviseur steekproefsgewijs dossiers controleren. Kies vaste momenten, zoals vóór verzending van de aanvraag. Leg vast wie wat controleerde. Zo heb je ook zonder groot team een kwaliteitscheck.`,tags:['vier-ogen','kwaliteit','klein-kantoor'],bron:''},
 {id:'psx-212',thema:'praktijk-software',vraag:'Hoe organiseer ik vervanging bij ziekte of vakantie?',antwoord:`Maak afspraken met een collega of samenwerkingspartner. Zorg dat dossiers en termijnen inzichtelijk zijn in de software. Informeer klanten over de vervanger. Leg de afspraken over toegang en geheimhouding vast.`,tags:['vervanging','continuïteit','kantoor'],bron:''},
 {id:'psx-213',thema:'praktijk-software',vraag:'Waarom is een continuïteitsregeling belangrijk voor een adviseur?',antwoord:`Bij langdurige uitval of overlijden moeten klanten verder kunnen. Een regeling legt vast wie de dossiers overneemt. Dit is ook in het belang van de klant. Leg de regeling schriftelijk vast.`,tags:['continuïteit','uitval','kantoor'],bron:''},
 {id:'psx-214',thema:'praktijk-software',vraag:'Hoe houd ik de vakbekwaamheid van medewerkers bij?',antwoord:`Registreer diplomas, PE-verplichtingen en afgeronde examens per medewerker. Gebruik een overzicht met vervaldata. Plan tijdig nieuwe examens. Leg het overzicht vast in je kantoordossier.`,tags:['vakbekwaamheid','pe','registratie'],bron:'Wft'},
 {id:'psx-215',thema:'praktijk-software',vraag:'Wat leg ik vast in mijn kantoorbrede werkinstructies?',antwoord:`Beschrijf het standaardproces van intake tot nazorg. Noteer wie welke stap doet en welke checklists gelden. Houd de instructies kort en actueel. Leg wijzigingen met datum vast.`,tags:['werkinstructies','proces','kantoor'],bron:''},
 {id:'psx-216',thema:'praktijk-software',vraag:'Hoe ga ik om met een assistent die dossiers voorbereidt?',antwoord:`Leg vast welke taken de assistent zelfstandig doet. Adviestaken vragen de juiste vakbekwaamheid. De adviseur blijft eindverantwoordelijk voor het advies. Controleer het werk volgens een vast proces.`,tags:['assistent','taakverdeling','verantwoordelijkheid'],bron:'Wft'},
 {id:'psx-217',thema:'praktijk-software',vraag:'Hoe richt ik toegangsrechten in de adviessoftware in?',antwoord:`Geef medewerkers alleen toegang tot wat ze nodig hebben. Gebruik persoonlijke accounts en tweestapsverificatie. Trek rechten direct in bij vertrek. Controleer periodiek wie toegang heeft.`,tags:['toegangsrechten','beveiliging','software'],bron:'AVG'},
 {id:'psx-218',thema:'praktijk-software',vraag:'Wat doe ik bij een datalek op kantoor?',antwoord:`Beoordeel direct wat er gelekt is en bij wie. Een datalek kan meldplichtig zijn bij de Autoriteit Persoonsgegevens en soms aan betrokkenen. Volg je interne procedure. Leg alle datalekken vast, ook als je niet meldt.`,tags:['datalek','avg','melding'],bron:'Autoriteit Persoonsgegevens'},
 {id:'psx-219',thema:'praktijk-software',vraag:'Heb ik een verwerkersovereenkomst nodig met mijn softwareleverancier?',antwoord:`Als de leverancier persoonsgegevens voor jou verwerkt, is een verwerkersovereenkomst nodig. Controleer of die is afgesloten en wat erin staat. Let op opslaglocatie en beveiliging. Bewaar de overeenkomst.`,tags:['verwerkersovereenkomst','avg','software'],bron:'AVG'},
 {id:'psx-220',thema:'praktijk-software',vraag:'Hoe houd ik een verwerkingsregister bij?',antwoord:`Noteer welke persoonsgegevens je verwerkt, waarom en hoe lang. Vermeld ontvangers zoals geldverstrekkers en verzekeraars. Werk het register bij als processen veranderen. Het register helpt bij vragen van toezichthouders.`,tags:['verwerkingsregister','avg','privacy'],bron:'AVG'},
 {id:'psx-221',thema:'praktijk-software',vraag:'Hoe ga ik om met een inzageverzoek van een klant?',antwoord:`Een klant heeft recht op inzage in zijn persoonsgegevens. Reageer binnen de wettelijke termijn. Controleer de identiteit van de aanvrager. Leg het verzoek en je reactie vast.`,tags:['inzageverzoek','avg','privacy'],bron:'AVG'},
 {id:'psx-222',thema:'praktijk-software',vraag:'Wat is eBlinqx Hypotheekadvies in de praktijk?',antwoord:`eBlinqx Hypotheekadvies is adviessoftware die in de markt ook bekendstaat als Fastlane. De software ondersteunt inventarisatie, berekeningen en aanvragen. Controleer de actuele functies bij de leverancier. Gebruik de uitkomsten altijd met eigen vakinhoudelijke controle.`,tags:['eblinqx','fastlane','adviessoftware'],bron:''},
 {id:'psx-223',thema:'praktijk-software',vraag:'Wat is een HBX-export uit Adviesbox Online?',antwoord:`Een HBX-bestand is een export van dossiergegevens uit Adviesbox Online. Het bestand bevat een GUID als unieke sleutel voor het dossier. Zo kunnen gegevens worden overgezet zonder alles opnieuw in te voeren. Controleer na import altijd de overgenomen gegevens.`,tags:['adviesbox','hbx','export'],bron:''},
 {id:'psx-224',thema:'praktijk-software',vraag:'Waarom is de GUID in een dossierexport belangrijk?',antwoord:`Een GUID is een unieke identificatie. Daarmee kan een systeem herkennen om welk dossier het gaat. Dat voorkomt dubbele of verkeerd gekoppelde dossiers. Wijzig de GUID niet handmatig.`,tags:['guid','export','dossierkoppeling'],bron:''},
 {id:'psx-225',thema:'praktijk-software',vraag:'Wat controleer ik na het importeren van een dossier in andere software?',antwoord:`Controleer persoonsgegevens, inkomen, leningdelen en verplichtingen. Kijk of velden goed zijn overgenomen of leeg zijn gebleven. Vergelijk de uitkomst met de bronsoftware. Leg vast dat je de import hebt gecontroleerd.`,tags:['import','controle','software'],bron:''},
 {id:'psx-226',thema:'praktijk-software',vraag:'Waarom kan dezelfde berekening in twee adviespakketten verschillen?',antwoord:`Pakketten kunnen andere rekenregels, afrondingen of normversies gebruiken. Ook standaardinstellingen verschillen. Controleer welke normen en uitgangspunten zijn gebruikt. Leg vast welk resultaat je in het advies gebruikt.`,tags:['adviessoftware','verschil','rekenregels'],bron:''},
 {id:'psx-227',thema:'praktijk-software',vraag:'Hoe houd ik de normen in mijn adviessoftware actueel?',antwoord:`Installeer updates van de leverancier tijdig. Controleer bij een jaarwisseling of de nieuwe normen zijn doorgevoerd. Test een bekende berekening na een update. Leg vast wanneer je dat hebt gecontroleerd.`,tags:['updates','normen','software'],bron:''},
 {id:'psx-228',thema:'praktijk-software',vraag:'Mag ik vertrouwen op de uitkomst van de adviessoftware?',antwoord:`Software ondersteunt, maar vervangt je oordeel niet. Je blijft verantwoordelijk voor het advies. Controleer opvallende uitkomsten en de invoer. Leg je eigen afweging vast naast de berekening.`,tags:['software','verantwoordelijkheid','controle'],bron:'Wft'},
 {id:'psx-229',thema:'praktijk-software',vraag:'Hoe voorkom ik invoerfouten in adviessoftware?',antwoord:`Werk met vaste invoervolgorde en checklists. Neem gegevens direct over van de bronstukken. Laat kritieke velden door een collega controleren. Controleer de berekening op plausibiliteit.`,tags:['invoerfouten','software','checklist'],bron:''},
 {id:'psx-230',thema:'praktijk-software',vraag:'Hoe bewaar ik adviesrapporten die de software genereert?',antwoord:`Sla de definitieve versie op als vaste pdf in het dossier. Bewaar ook de versie die de klant heeft ontvangen. Leg datum en versie vast. Zo blijft het rapport ongewijzigd bij latere vragen.`,tags:['adviesrapport','archivering','software'],bron:''},
 {id:'psx-231',thema:'praktijk-software',vraag:'Wat doe ik als de adviessoftware tijdelijk niet beschikbaar is?',antwoord:`Informeer klanten bij vertraging. Werk zo nodig met handmatige berekeningen, maar leg dat vast. Verwerk alles achteraf in de software. Bewaak termijnen extra zorgvuldig.`,tags:['storing','software','continuïteit'],bron:''},
 {id:'psx-232',thema:'praktijk-software',vraag:'Hoe ga ik om met koppelingen tussen software en geldverstrekkers?',antwoord:`Koppelingen versnellen het berichtenverkeer, maar kunnen fouten doorgeven. Controleer of de juiste gegevens worden verzonden. Let op foutmeldingen en statusberichten. Leg storingen vast.`,tags:['koppelingen','hdn','software'],bron:'HDN'},
 {id:'psx-233',thema:'praktijk-software',vraag:'Wat zijn risicos van het kopiëren van een oud dossier als sjabloon?',antwoord:`Oude gegevens kunnen ongemerkt in het nieuwe advies belanden. Denk aan inkomen, normen of productvoorwaarden. Gebruik liever een leeg sjabloon. Controleer elk overgenomen veld.`,tags:['sjabloon','dossier','fouten'],bron:''},
 {id:'psx-234',thema:'praktijk-software',vraag:'Hoe stel ik standaardteksten in mijn adviesrapport op?',antwoord:`Gebruik standaardteksten voor algemene uitleg. Maak het advies zelf persoonlijk en koppel het aan de klantsituatie. Controleer standaardteksten periodiek op actualiteit. Te algemene teksten zijn zwak bij toetsing.`,tags:['standaardteksten','adviesrapport','maatwerk'],bron:'AFM'},
 {id:'psx-235',thema:'praktijk-software',vraag:'Hoe ga ik om met e-handtekeningen van klanten?',antwoord:`Gebruik een betrouwbare dienst die vastlegt wie tekende en wanneer. Controleer of de geldverstrekker digitale handtekening accepteert. Bewaar het ondertekende document met het bewijs. Leg je werkwijze vast.`,tags:['e-handtekening','digitaal','dossier'],bron:''},
 {id:'psx-236',thema:'praktijk-software',vraag:'Hoe richt ik een klantportaal in voor het uitwisselen van stukken?',antwoord:`Kies een portaal met goede beveiliging en logging. Leg uit aan de klant hoe het werkt. Stel bewaartermijnen in en ruim op. Controleer de verwerkersovereenkomst met de leverancier.`,tags:['klantportaal','beveiliging','avg'],bron:'AVG'},
 {id:'psx-237',thema:'praktijk-software',vraag:'Wat leg ik vast over mijn beloningsbeleid?',antwoord:`Leg vast hoe medewerkers worden beloond en hoe je belangenconflicten voorkomt. Beloning mag het klantbelang niet schaden. Toets het beleid periodiek. Bewaar de vastlegging in het kantoordossier.`,tags:['beloningsbeleid','belangenconflict','kantoor'],bron:'Wft'},
 {id:'psx-238',thema:'praktijk-software',vraag:'Hoe ga ik om met een uurtarief versus een vast tarief?',antwoord:`Leg de keuze vast in de opdrachtbevestiging. Bij een uurtarief geef je een inschatting van het aantal uren. Bij een vast tarief beschrijf je wat erin zit. Bespreek wat er gebeurt als het traject stopt.`,tags:['tarief','vergoeding','opdracht'],bron:''},
 {id:'psx-239',thema:'praktijk-software',vraag:'Wat leg ik vast als een traject wordt afgebroken en ik toch kosten wil rekenen?',antwoord:`Leg vooraf vast in de opdrachtbevestiging wat de klant betaalt bij afbreken. Registreer de verrichte werkzaamheden. Stuur een duidelijke factuur met toelichting. Zonder vooraf gemaakte afspraken is discussie waarschijnlijker.`,tags:['afgebroken','kosten','opdrachtbevestiging'],bron:''},
 {id:'psx-240',thema:'praktijk-software',vraag:'Hoe controleer ik periodiek de kwaliteit van mijn dossiers?',antwoord:`Kies een steekproef van recente dossiers. Toets op volledigheid, onderbouwing en vastlegging. Noteer bevindingen en verbeterpunten. Herhaal de controle op vaste momenten.`,tags:['dossiercontrole','steekproef','kwaliteit'],bron:'AFM'},
 {id:'psx-241',thema:'praktijk-software',vraag:'Hoe bereid ik me voor op een onderzoek van de AFM?',antwoord:`Zorg voor actuele procedures, een verwerkingsregister, vakbekwaamheidsoverzicht en goed gevulde dossiers. Weet waar documenten staan. Wijs een contactpersoon aan. Reageer binnen de gevraagde termijnen.`,tags:['afm','toezicht','voorbereiding'],bron:'AFM'},
 {id:'psx-242',thema:'praktijk-software',vraag:'Wat doe ik als een geldverstrekker een dossier terugstuurt om fouten?',antwoord:`Corrigeer de fouten snel en controleer het hele dossier opnieuw. Zoek de oorzaak in je proces. Pas zo nodig je checklist aan. Leg de terugkoppeling vast als leermoment.`,tags:['terugkoppeling','fouten','kwaliteit'],bron:''},
 {id:'psx-243',thema:'praktijk-software',vraag:'Hoe houd ik productvoorwaarden van geldverstrekkers bij in de praktijk?',antwoord:`Gebruik de informatie in je software en de actuele publicaties van geldverstrekkers. Controleer bij twijfel direct bij de geldverstrekker. Noteer de geraadpleegde versie in het dossier. Wijzigingen gaan soms snel.`,tags:['productvoorwaarden','actualiteit','geldverstrekker'],bron:''},
 {id:'psx-244',thema:'praktijk-software',vraag:'Hoe ga ik om met een bemiddelingsovereenkomst bij een geldverstrekker?',antwoord:`Je hebt meestal een overeenkomst nodig om aanvragen te mogen indienen. Lees de voorwaarden over verantwoordelijkheden en fraudebeleid. Houd de overeenkomsten bij in je kantoordossier. Controleer tijdig verlenging of wijzigingen.`,tags:['bemiddelingsovereenkomst','geldverstrekker','kantoor'],bron:''},
 {id:'psx-245',thema:'praktijk-software',vraag:'Hoe ga ik om met een fraudesignaal bij een aanvraag?',antwoord:`Stop de aanvraag en onderzoek het signaal. Verstuur geen stukken waaraan je twijfelt. Volg de afspraken met de geldverstrekker en je interne procedure. Leg je bevindingen en beslissing vast.`,tags:['fraude','signaal','procedure'],bron:''},
 {id:'psx-246',thema:'praktijk-software',vraag:'Hoe leg ik vast welke geldverstrekkers ik heb vergeleken?',antwoord:`Noteer welke partijen je hebt bekeken en op welke criteria. Leg de reden voor de gekozen partij vast. Vermeld ook waarom andere opties afvielen. Bewaar de vergelijking in het dossier.`,tags:['vergelijking','geldverstrekkers','vastlegging'],bron:'Wft'},
 {id:'psx-247',thema:'praktijk-software',vraag:'Hoe ga ik om met een samenwerking met een makelaar of bouwer?',antwoord:`Leg de afspraken over vergoedingen en doorverwijzing vast. Zorg dat de klant weet dat er een samenwerking is. Je advies moet onafhankelijk blijven van deze relatie. Beoordeel periodiek of er belangenconflicten zijn.`,tags:['samenwerking','belangenconflict','transparantie'],bron:'Wft'},
 {id:'psx-248',thema:'praktijk-software',vraag:'Hoe richt ik een agenda voor termijnbewaking in?',antwoord:`Maak per dossier herinneringen voor alle harde data. Plan een signaal ruim vóór elke deadline. Koppel de agenda aan de status van het dossier. Controleer wekelijks de lopende termijnen.`,tags:['agenda','termijnbewaking','planning'],bron:''},
 {id:'psx-249',thema:'praktijk-software',vraag:'Hoe documenteer ik telefonische afspraken met een klant?',antwoord:`Maak kort na het gesprek een notitie met datum en kern van de afspraak. Stuur belangrijke afspraken per bericht ter bevestiging. Sla de notitie op in het dossier. Zo blijft ook mondeling contact te volgen.`,tags:['telefoon','vastlegging','communicatie'],bron:''},
 {id:'psx-250',thema:'praktijk-software',vraag:'Wat doe ik als een klant na een klacht een vergoeding vraagt?',antwoord:`Beoordeel of er sprake is van een fout en van schade. Overleg vóór toezeggingen met je beroepsaansprakelijkheidsverzekeraar. Erken geen aansprakelijkheid zonder die afstemming. Leg het verloop vast.`,tags:['schadevergoeding','klacht','bav'],bron:''},
]);
